def _list_input_devices_inproc():
    """In-process input device enumeration. Used as a frozen-mode
    fallback and for the very first read before the watchdog has
    populated the cache. May return stale data on Windows because
    PortAudio's MME backend caches the device list at process level
    — that's exactly what _enumerate_devices_via_subprocess() avoids."""
    devices = []
    try:
        import pyaudio
        pa = pyaudio.PyAudio()
        try:
            try:
                default_host_api = pa.get_default_host_api_info().get("index")
            except Exception:
                default_host_api = None

            seen_names = set()
            for i in range(pa.get_device_count()):
                info = pa.get_device_info_by_index(i)
                if int(info.get("maxInputChannels", 0)) <= 0:
                    continue
                if default_host_api is not None and info.get("hostApi") != default_host_api:
                    continue
                name = str(info.get("name", f"Device {i}")).strip()
                if name.lower() in ("microsoft sound mapper - input", "primary sound capture driver"):
                    continue
                if name in seen_names:
                    continue
                seen_names.add(name)
                devices.append((i, name))
        finally:
            pa.terminate()
    except Exception as e:
        log.error("Failed to list input devices: %s", e)
    return devices


def _list_loopback_devices_inproc():
    """In-process loopback device enumeration. See _list_input_devices_inproc
    for why this is fallback-only on Windows."""
    devices = []
    try:
        import pyaudiowpatch as pyaudio
        pa = pyaudio.PyAudio()
        try:
            seen_names = set()
            for loopback in pa.get_loopback_device_info_generator():
                name = str(loopback.get("name", "")).strip()
                clean_name = name.replace("[Loopback]", "").strip()
                if not clean_name:
                    continue
                if clean_name in seen_names:
                    continue
                seen_names.add(clean_name)
                devices.append((int(loopback["index"]), clean_name))
        finally:
            pa.terminate()
    except ImportError:
        log.warning("pyaudiowpatch not installed - cannot list loopback devices")
    except Exception as e:
        log.error("Failed to list loopback devices: %s", e)
    return devices


def list_input_devices():
    """Cached input device list. Always reflects the most recent device
    state on Windows because the device watchdog refreshes the cache via
    a fresh subprocess (see _enumerate_devices_via_subprocess)."""
    with _device_cache_lock:
        if _device_cache["ready"]:
            return list(_device_cache["mic"])
    # First call before any watchdog refresh — populate now via the
    # subprocess so even a freshly-launched app sees current devices.
    _refresh_device_cache()
    with _device_cache_lock:
        return list(_device_cache["mic"])


def list_loopback_devices():
    """Cached loopback device list. See list_input_devices."""
    with _device_cache_lock:
        if _device_cache["ready"]:
            return list(_device_cache["loop"])
    _refresh_device_cache()
    with _device_cache_lock:
        return list(_device_cache["loop"])


def resample_audio(audio, orig_rate, target_rate):
    """Resample audio from orig_rate to target_rate using linear interpolation."""
    if orig_rate == target_rate or len(audio) == 0:
        return audio
    target_len = int(len(audio) * target_rate / orig_rate)
    return np.interp(
        np.linspace(0, len(audio) - 1, target_len),
        np.arange(len(audio)),
        audio,
    ).astype(np.float32)


def mix_audio(audio1, audio2):
    """Mix two audio arrays together, normalizing to prevent clipping."""
    if len(audio1) == 0:
        return audio2
    if len(audio2) == 0:
        return audio1

    # Pad the shorter array
    max_len = max(len(audio1), len(audio2))
    if len(audio1) < max_len:
        audio1 = np.pad(audio1, (0, max_len - len(audio1)))
    if len(audio2) < max_len:
        audio2 = np.pad(audio2, (0, max_len - len(audio2)))

    mixed = audio1 + audio2
    max_val = np.max(np.abs(mixed))
    if max_val > 1.0:
        mixed = mixed / max_val
    return mixed


# Both Groq and OpenAI's /audio/transcriptions enforce a 25 MB request
# body cap. We round down a hair to leave room for multipart overhead.
CLOUD_FILE_SIZE_LIMIT_BYTES = 24 * 1024 * 1024  # 24 MB


# Mapping from file extension to MIME for cloud audio uploads.
# Both APIs accept any of: mp3, mp4, m4a, wav, mpeg, mpga, flac, ogg, webm.
# Hardcoding `audio/mpeg` for everything causes the API to reject `.m4a`
# because the magic bytes don't match the declared MIME — files reported
# as "unsupported format" or get a generic 400.
_AUDIO_MIME_BY_EXT = {
    ".mp3": "audio/mpeg",
    ".mpga": "audio/mpeg",
    ".mpeg": "audio/mpeg",
    ".m4a": "audio/mp4",
    ".mp4": "audio/mp4",
    ".wav": "audio/wav",
    ".webm": "audio/webm",
    ".ogg": "audio/ogg",
    ".oga": "audio/ogg",
    ".flac": "audio/flac",
}


def guess_audio_mime(file_path):
    """Guess MIME type for an audio file from its extension.

    Falls back to `application/octet-stream` (generic binary) which both
    Groq and OpenAI accept and then sniff for content.
    """
    ext = os.path.splitext(file_path)[1].lower()
    return _AUDIO_MIME_BY_EXT.get(ext, "application/octet-stream")


def _read_wav_mono_16k(path):
    """Read a PCM16 WAV into an int16 mono numpy array (stdlib only, no
    soundfile/ffmpeg). Meeting WAVs are already 16 kHz mono, so this needs no
    resampling; a non-16 kHz file is returned as-is with a warning (the caller's
    encoder assumes 16 kHz). Returns None on any read error / non-PCM16 file."""
    try:
        with wave.open(path, "rb") as wf:
            nch = wf.getnchannels()
            sw = wf.getsampwidth()
            fr = wf.getframerate()
            raw = wf.readframes(wf.getnframes())
        if sw != 2:
            log.warning("_read_wav_mono_16k: %s is %d-byte samples, not PCM16", path, sw)
            return None
        audio = np.frombuffer(raw, dtype=np.int16)
        if nch > 1:
            audio = audio.reshape(-1, nch).mean(axis=1).astype(np.int16)
        if fr != 16000:
            log.warning("_read_wav_mono_16k: %s is %d Hz, not 16 kHz - timings "
                        "may be scaled by the fixed-rate encoder", path, fr)
        return audio
    except Exception as e:
        log.error("_read_wav_mono_16k failed for %s: %s", path, e)
        return None


def audio_peak_rms(audio_np, sample_rate=16000, window_ms=300):
    """Peak RMS over sliding windows (50% overlap), normalised to [0, 1].

    Used for silent-capture detection. Mean RMS over a whole clip
    under-reports when the user said one short word in an otherwise
    silent 2s clip (a natural press-to-talk pattern) — the brief speech
    is diluted by the surrounding silence and averages below the "mic
    silent" threshold, producing false alarms. Peak RMS looks at the
    loudest 300ms window and answers the actual question: "was there
    speech SOMEWHERE in this clip?"

    Accepts int16 or float32 numpy array; always returns a number in the
    same scale as float32 in [-1, 1].
    """
    if len(audio_np) == 0:
        return 0.0
    if audio_np.dtype == np.int16:
        samples = audio_np.astype(np.float32) / 32768.0
    else:
        samples = audio_np.astype(np.float32)
    window_samples = int(window_ms / 1000.0 * sample_rate)
    if window_samples < 1 or len(samples) < window_samples:
        return float(np.sqrt(np.mean(samples ** 2) + 1e-12))
    max_rms = 0.0
    hop = max(1, window_samples // 2)
    for i in range(0, len(samples) - window_samples + 1, hop):
        w = samples[i:i + window_samples]
        rms = float(np.sqrt(np.mean(w ** 2) + 1e-12))
        if rms > max_rms:
            max_rms = rms
    return max_rms


def apply_auto_gain(audio_np, target_rms=0.06, max_gain=8.0):
    """Boost quiet recordings toward a target loudness so the ASR has
    a stronger signal to work with — addresses 'it misses words' on
    low-level mics (e.g. a gooseneck set to a modest Windows input
    level). Only ever AMPLIFIES; never attenuates loud audio.

    Two ceilings keep it safe:
      - max_gain caps total boost (so a near-silent clip's noise floor
        isn't blown up into garbage that the model then hallucinates on).
      - a clipping ceiling (0.97 / peak) ensures the boosted signal
        never hard-clips, which would distort and HURT recognition.

    Returns float32 in [-1, 1]. Pass the FULL-clip audio AFTER the
    silent-capture guard has already rejected genuine silence, so we
    never amplify a dead-mic recording into a false positive.
    """
    if len(audio_np) == 0:
        return audio_np
    samples = (audio_np.astype(np.float32) / 32768.0
               if audio_np.dtype == np.int16 else audio_np.astype(np.float32))
    rms = float(np.sqrt(np.mean(samples ** 2) + 1e-12))
    if rms < 1e-5:
        return audio_np  # effectively silent — don't amplify noise
    gain = target_rms / rms
    # Only boost (never quieten a clip that's already loud enough).
    gain = max(1.0, min(gain, max_gain))
    peak = float(np.max(np.abs(samples)))
    if peak > 0:
        # Don't let the boost push the peak past 0.97 (avoid clipping).
        gain = min(gain, 0.97 / peak)
    gain = max(1.0, gain)
    if gain <= 1.01:
        return audio_np  # negligible — return original untouched
    boosted = np.clip(samples * gain, -1.0, 1.0)
    return boosted.astype(np.float32)


def smart_cut_tail(audio_np, sample_rate=16000, window_s=2.5, frame_s=0.03,
                   min_carry_s=0.15):
    """Split `audio_np` at the QUIETEST frame inside its last `window_s`
    seconds, returning (head, tail). The meeting rotation drains audio at an
    arbitrary wall-clock moment, so the raw boundary can land mid-word; moving
    the cut to the least-energetic point near the end and carrying the tail
    into the NEXT chunk means a boundary word is transcribed whole, once
    (Meetily-inspired, 2026-08-27). Returns (audio_np, None) when the audio is
    too short to bother or the best cut is closer than `min_carry_s` to the end
    (nothing meaningful to carry)."""
    n = len(audio_np) if audio_np is not None else 0
    fr = max(1, int(frame_s * sample_rate))
    win_n = int(window_s * sample_rate)
    if n < 2 * win_n:            # too short: keep the historical behavior
        return audio_np, None
    seg = np.asarray(audio_np[n - win_n:], dtype=np.float32)
    nf = len(seg) // fr
    if nf < 2:
        return audio_np, None
    frames = seg[:nf * fr].reshape(nf, fr)
    rms = np.sqrt(np.mean(frames * frames, axis=1) + 1e-12)
    # Quietest frame's midpoint = the cut. Even in continuous speech this is
    # at worst as arbitrary as the drain moment itself, and usually a pause.
    best = int(np.argmin(rms))
    cut = (n - win_n) + best * fr + fr // 2
    if n - cut < int(min_carry_s * sample_rate):
        return audio_np, None
    return audio_np[:cut], audio_np[cut:]


def scan_speaker_turns(content):
    """Parse a diarized transcript's '[mm:ss] Speaker X:' headers into
    [(label, hint, best_start_s)] in first-appearance order (pure, testable).
    `hint` = the first non-empty text line after the speaker's FIRST turn;
    `best_start_s` = the start of the speaker's LONGEST turn - the snippet a
    'play' button should preview (a substantive turn identifies a voice far
    better than a 2-word interjection). Named speakers (already-renamed lines
    like 'נאור:') are not matched - only unnamed 'Speaker X' labels."""
    import re as _re
    hdr = _re.compile(r"\[(?:(\d+):)?(\d{1,2}):(\d{2})\]\s*Speaker (\w+):")
    lines = (content or "").splitlines()
    order, first_hint, best = [], {}, {}   # label -> (text_len, start_s)
    for i, ln in enumerate(lines):
        m = hdr.search(ln)
        if not m:
            continue
        h, mn, sc, label = m.groups()
        start_s = (int(h) * 3600 if h else 0) + int(mn) * 60 + int(sc)
        text = ""
        for j in range(i + 1, min(i + 4, len(lines))):
            s = lines[j].strip().lstrip("‏‎").strip()
            if s and not hdr.search(lines[j]):
                text = s
                break
        if label not in first_hint:
            order.append(label)
            first_hint[label] = text[:48]
        if len(text) > best.get(label, (-1, 0))[0]:
            best[label] = (len(text), start_s)
    return [(lab, first_hint[lab], best.get(lab, (0, 0))[1]) for lab in order]


def extract_audio_segment(src_path, start_s, dur_s, out_path):
    """Cut [start_s, start_s+dur_s] out of a meeting audio file into a 16k mono
    WAV at out_path, for the rename dialog's per-speaker voice preview.
    WAV input: exact frame seek via the wave module. OPUS input (the long-term
    archive): decode via PyAV with a container seek. Returns True when audio
    was written."""
    import wave
    if (src_path or "").lower().endswith(".wav"):
        with wave.open(src_path, "rb") as r:
            sr, ch, sw = r.getframerate(), r.getnchannels(), r.getsampwidth()
            r.setpos(min(int(start_s * sr), r.getnframes()))
            frames = r.readframes(int(dur_s * sr))
        if not frames:
            return False
        with wave.open(out_path, "wb") as w:
            w.setnchannels(ch)
            w.setsampwidth(sw)
            w.setframerate(sr)
            w.writeframes(frames)
        return True
    import av
    container = av.open(src_path)
    try:
        stream = container.streams.audio[0]
        try:
            container.seek(int(max(0.0, start_s - 0.5) * 1000000))
        except Exception:
            pass   # some containers refuse seek - decode from the top
        res = av.AudioResampler(format="s16", layout="mono", rate=16000)
        chunks, got = [], 0.0
        for frame in container.decode(stream):
            t = (float(frame.pts * stream.time_base)
                 if frame.pts is not None else None)
            if t is not None and t + (frame.samples / float(frame.sample_rate)) < start_s:
                continue
            for rf in res.resample(frame):
                chunks.append(rf.to_ndarray().tobytes())
                got += rf.samples / 16000.0
            if got >= dur_s:
                break
    finally:
        container.close()
    if not chunks:
        return False
    with wave.open(out_path, "wb") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(16000)
        w.writeframes(b"".join(chunks)[:int(dur_s * 16000) * 2])
    return True


# ---- Speaker naming, phase 2: LLM name-assignment pass (LOCAL only) ---------
# A narrow gemma call matches still-unnamed diarized labels to CALENDAR
# candidate names from conversational evidence (self-intros, being addressed
# by name and answering). Evidence-or-nothing discipline: the model may only
# pick from the candidate list, CODE enforces membership + uniqueness, and
# anything else leaves the label as 'Speaker X'.

_SPEAKER_NAME_PASS_PROMPT = (
    "You are matching diarized speaker labels to real participant names in a raw Hebrew meeting "
    "transcript (Israeli tech/business meeting, Hebrew with English terms).\n"
    "Evidence that identifies a speaker:\n"
    "- a self-introduction (\"שלום, אני דנה\", \"מדבר אבי\", \"זאת מיכל מהנהלת חשבונות\");\n"
    "- someone ADDRESSES a person by name with a question and the NEXT speaker answers it;\n"
    "- thanking the PREVIOUS speaker by name (\"תודה דנה\" right after Speaker B spoke => B is דנה).\n"
    "NOT evidence: a speaker merely MENTIONING another participant's name says nothing about "
    "who the speaker themself is.\n"
    "Rules:\n"
    "- Only use names from the CANDIDATES list, exactly as written there. Never invent a name.\n"
    "- Assign a name ONLY on explicit evidence in the transcript; when uncertain, output אין.\n"
    "- Each name may be assigned to at most ONE speaker label.\n"
    "Output: one line per speaker label, exactly 'X: <candidate name>' or 'X: אין'. Nothing else."
)


def _speaker_name_evidence(utterances, unnamed, head_chars=8000, per_speaker=3,
                           cap_chars=14000):
    """The excerpt the name pass reads: the meeting's chronological HEAD (where
    people introduce themselves) + each unnamed speaker's longest turns (where
    they are most identifiable). Pure; returns a 'Speaker X: text' block."""
    lines, used, total = [], set(), 0
    for i, u in enumerate(utterances):
        t = (u.get("text") or "").strip()
        if not t:
            continue
        ln = "Speaker %s: %s" % (u.get("speaker"), t)
        if total + len(ln) > head_chars:
            break
        lines.append(ln)
        used.add(i)
        total += len(ln) + 1
    for lab in unnamed:
        turns = sorted(
            ((len((u.get("text") or "").strip()), i) for i, u in enumerate(utterances)
             if u.get("speaker") == lab and i not in used
             and (u.get("text") or "").strip()),
            reverse=True)[:per_speaker]
        for _n, i in sorted(turns, key=lambda x: x[1]):
            u = utterances[i]
            ln = "Speaker %s: %s" % (lab, (u.get("text") or "").strip())
            if total + len(ln) > cap_chars:
                break
            lines.append(ln)
            used.add(i)
            total += len(ln) + 1
    return "\n".join(lines)


def _parse_speaker_name_votes(text, unnamed, candidates, taken=()):
    """'X: name' lines -> {label: candidate}. CODE enforces the contract: the
    label must be one we asked about, the name must be a candidate (casefold
    match, exact text taken from the candidate list), never a name already in
    use, and never the same name for two labels. 'אין'/junk contribute nothing."""
    out = {}
    cand_by_fold = {c.casefold(): c for c in candidates}
    used = {t.casefold() for t in taken}
    for line in (text or "").splitlines():
        m = _re_tasks.match(r"^\s*(?:Speaker\s+)?(\w+)\s*[:.]\s*(.+?)\s*$",
                            line.strip())
        if not m:
            continue
        lab, name = m.group(1), m.group(2).strip().strip(".").strip('"')
        if lab not in unnamed or lab in out:
            continue
        c = cand_by_fold.get(name.casefold())
        if c is None or c.casefold() in used:
            continue
        out[lab] = c
        used.add(c.casefold())
    return out


def pick_self_speaker(utterances, mic_rms, loop_rms,
                      min_speech_s=3, min_ratio=0.4, min_margin=0.5):
    """Speaker naming, phase 1b (pure): which diarized speaker label is the
    LOCAL user. For every utterance interval, compare the MIC channel's mean
    RMS with the LOOPBACK channel's (both 1s bins along the meeting timeline);
    per speaker, aggregate the duration-weighted log-ratio. The local user's
    turns are mic-dominant; remote speakers are loopback-dominant (acoustic
    bleed from speakers into the mic only weakens the ratio, it does not flip
    it). Conservative by design: returns (label, margin) only when the top
    speaker is clearly mic-dominant (>= min_ratio in log space) AND clearly
    separated from the runner-up (>= min_margin); else (None, 0.0).
    Requires a real loopback track - a mic-only meeting has no 'which side'
    signal and every cluster would look mic-dominant."""
    import math
    if not utterances or not mic_rms or not loop_rms:
        return None, 0.0
    if max(loop_rms) <= 0:
        return None, 0.0
    n = min(len(mic_rms), len(loop_rms))
    agg = {}
    for u in utterances:
        lab = u.get("speaker")
        if not lab:
            continue
        s = max(0, int(float(u.get("start") or 0) / 1000.0))
        e = min(n, int(math.ceil(float(u.get("end") or 0) / 1000.0)))
        if e - s < 1:
            continue
        m = sum(mic_rms[s:e]) / (e - s)
        l = sum(loop_rms[s:e]) / (e - s)
        w = e - s
        a = agg.setdefault(lab, [0.0, 0.0])
        a[0] += math.log((m + 1e-9) / (l + 1e-9)) * w
        a[1] += w
    avg = {k: v[0] / v[1] for k, v in agg.items() if v[1] >= min_speech_s}
    if not avg:
        return None, 0.0
    ranked = sorted(avg.items(), key=lambda kv: kv[1], reverse=True)
    top_lab, top = ranked[0]
    second = ranked[1][1] if len(ranked) > 1 else -math.inf
    margin = top - second
    if top >= min_ratio and margin >= min_margin:
        return top_lab, margin
    return None, 0.0


def trim_trailing_silence(audio_np, sample_rate=16000, threshold_db=-45, tail_ms=500):
    """Trim silence from the end of audio to reduce Whisper end-of-clip hallucinations
    like 'thank you' / 'תודה רבה'. Keeps `tail_ms` of trailing buffer.

    Expects float32 or int16 numpy array, mono.

    Tuning: threshold_db=-45 (was -40) keeps quiet/whispered tail speech
    instead of trimming it as silence. tail_ms=500 (was 150) gives
    Whisper enough silence after the last word to reliably end-cap the
    transcription; 150ms occasionally caused Whisper to drop the final
    word or two because the clip ended too abruptly. 500ms is still well
    under the threshold for hallucinations (which need ~2s+ of silence).
    """
    if len(audio_np) == 0:
        return audio_np

    # Convert to float32 in [-1, 1] for RMS calc
    if audio_np.dtype == np.int16:
        samples = audio_np.astype(np.float32) / 32768.0
    else:
        samples = audio_np.astype(np.float32)

    window = int(0.02 * sample_rate)  # 20ms windows
    if window < 1 or len(samples) < window:
        return audio_np

    threshold = 10 ** (threshold_db / 20.0)  # -40 dB ≈ 0.01 amplitude

    # Walk back from end, looking for the last non-silent window
    tail_samples = int(tail_ms / 1000.0 * sample_rate)
    i = len(samples) - window
    while i > 0:
        rms = float(np.sqrt(np.mean(samples[i:i + window] ** 2) + 1e-12))
        if rms > threshold:
            cut = min(len(audio_np), i + window + tail_samples)
            return audio_np[:cut]
        i -= window

    # Entire clip is "silence" — return as-is
    return audio_np


# Regex patterns for common Whisper end-of-clip hallucinations.
# Matched at the VERY END of the text, case-insensitive for English.
# Each pattern captures optional trailing punctuation so we strip that too.
# Every phrase is anchored to a WORD START (^ or whitespace) — without it,
# bare substring matches cut MID-WORD: 'הכל עבר בשלום' matched 'שלום$' and
# pasted as 'הכל עבר ב' (Hebrew prefix letters ב/ל/ו attach to words).
_HALLUCINATION_PATTERNS = [
    # English
    r"(?:^|\s)thank\s+you(\s+very\s+much|\s+for\s+watching|\s+for\s+listening|\s+all)?\s*[!.?,]*\s*$",
    r"(?:^|\s)thanks(\s+for\s+watching|\s+for\s+listening|\s+a\s+lot)?\s*[!.?,]*\s*$",
    r"(?:^|\s)bye(\s+bye)?\s*[!.?,]*\s*$",
    r"(?:^|\s)goodbye\s*[!.?,]*\s*$",
    r"(?:^|\s)see\s+you\s+next\s+time\s*[!.?,]*\s*$",
    # Hebrew
    r"(?:^|\s)תודה(\s+רבה(\s+לכם)?)?\s*[!.?,]*\s*$",
    r"(?:^|\s)תודה\s+שצפיתם\s*[!.?,]*\s*$",
    r"(?:^|\s)תודה\s+על\s+הצפייה\s*[!.?,]*\s*$",
    r"(?:^|\s)להתראות\s*[!.?,]*\s*$",
    # שלום / בהצלחה are common REAL sentence-enders ("עברה בהצלחה",
    # "תגיד שלום") — strip them only when they are the ENTIRE clip
    # (the pure silence-hallucination case), never off a real sentence.
    r"^בהצלחה\s*[!.?,]*\s*$",
    r"^שלום\s*[!.?,]*\s*$",
]

_HALLUCINATION_REGEXES = None


def _rms_energy(audio_np):
    """RMS level of a clip, robust to float32 (-1..1) or int16 input; 0.0 on
    empty/error. Used to tell a genuinely SILENT meeting chunk (VAD correctly
    strips it → empty text) apart from a real transcription failure, so silence
    isn't mislabeled '[transcription failed]'."""
    try:
        a = np.asarray(audio_np, dtype=np.float32)
        if a.size == 0:
            return 0.0
        if float(np.max(np.abs(a))) > 1.5:   # int16-range → normalise to -1..1
            a = a / 32768.0
        return float(np.sqrt(np.mean(a * a)))
    except Exception:
        return 0.0


def _get_hallucination_regexes():
    """Lazy-compile patterns once."""
    global _HALLUCINATION_REGEXES
    if _HALLUCINATION_REGEXES is None:
        import re
        _HALLUCINATION_REGEXES = [re.compile(p, re.IGNORECASE | re.UNICODE)
                                    for p in _HALLUCINATION_PATTERNS]
    return _HALLUCINATION_REGEXES


def strip_hallucinated_tail(text):
    """Remove known trailing hallucinations from a transcription.

    Whisper frequently produces "Thank you" / "תודה רבה" / "bye" when the
    input audio is silent or too quiet to contain real speech. These
    phrases almost never match what the user actually said, so we strip
    them. If the matched phrase is the entire output, we return empty —
    pasting a random "תודה רבה" into the user's document (from silent
    audio) is MORE disruptive than no paste at all.

    The caller is expected to surface a visible error indicator when
    the transcription comes back empty (we flash the tray icon red for
    3s in do_transcribe, so silent_mode users still see feedback).
    """
    if not text:
        return text
    import re
    # gpt-4o-transcribe prepends bidi marks (RLM/LRM) to Hebrew output, and the
    # anchored patterns (^ / \s) won't match across an invisible leading mark —
    # so a silent-clip hallucination "‏תודה רבה" would slip through unstripped
    # and get pasted. Strip the marks before matching (they're cosmetic).
    cleaned = re.sub("[\\u200e\\u200f\\u202a-\\u202e\\u2066-\\u2069]", "", text).rstrip()
    regexes = _get_hallucination_regexes()

    for _ in range(3):
        found = False
        for rx in regexes:
            m = rx.search(cleaned)
            if m:
                removed = m.group(0).strip()
                # Cut the match and trim trailing punctuation/whitespace
                cleaned = cleaned[:m.start()]
                cleaned = re.sub(r'[\s.!?,;:،۔؟]+$', '', cleaned)
                log.info("Stripped hallucinated tail: %r", removed)
                found = True
                break
        if not found:
            break

    return cleaned.strip()


_CHAR_RUN_HALLUCINATION_RE = None


def _collapse_char_runs(text):
    """Collapse runs of >=5 of the same character to 3 chars + ellipsis.

    Catches stuck-decoder hallucinations like 'אהההההההה...' or 'aaaaaaa'
    that Whisper-family models (and AssemblyAI universal-2) sometimes
    emit on silence / extreme low-volume audio. The collapsed form
    preserves the user's awareness that something noisy was there
    while making the transcript readable."""
    global _CHAR_RUN_HALLUCINATION_RE
    if _CHAR_RUN_HALLUCINATION_RE is None:
        import re as _re
        # LETTERS ONLY ([^\W\d_] = unicode letter): stuck-decoder runs are
        # letter noise ('אהההה', 'aaaaa'). Digits/whitespace/punctuation must
        # survive — '0505555555' is a dictated phone number, not a glitch
        # (collapsing it silently corrupted pasted numbers).
        _CHAR_RUN_HALLUCINATION_RE = _re.compile(r'([^\W\d_])\1{4,}')
    return _CHAR_RUN_HALLUCINATION_RE.sub(
        lambda m: m.group(1) * 3 + '…', text)


def _min_repeats_for_phrase_size(k):
    """Per-phrase-size repetition threshold tuned to catch hallucinations
    without misfiring on natural-speech stuttering.

      k = 1: need 5+ reps  (single-word stutters like 'yes yes yes yes yes')
      k = 2: need 4+ reps  ('uh huh, uh huh, uh huh' borderline natural)
      k = 3: need 3+ reps  (rarely natural)
      k >= 4: need 3+ reps (essentially never natural)
    """
    if k >= 3:
        return 3
    if k == 2:
        return 4
    return 5


def _collapse_phrase_repetitions(text, max_phrase_words=20):
    """Collapse immediate consecutive identical phrase repetitions.

    A 'phrase' is a sequence of 1..max_phrase_words whitespace-separated
    tokens. If the same phrase appears N times in a row where N meets
    the per-size threshold, collapse to a single occurrence.

    Catches stuck-loop transcription hallucinations like
    'ונדבר על פרס המדינה, ונדבר על פרס המדינה, ונדבר על פרס המדינה...'
    that AssemblyAI universal-2 emits on the pre-speech silence at the
    start of a meeting recording.

    SMALLEST-K FIRST is critical: a greedy-LARGEST-first scan would
    match a larger super-phrase (e.g. 5 copies of the 4-word loop = a
    20-word phrase) which "found" only 2 super-phrase reps in 30 inner
    reps and bailed, leaving 5+ inner copies behind. Smallest-first
    finds the true period (k=4) and collapses cleanly.
    """
    words = text.split()
    if len(words) < 3:
        return text
    result = []
    i = 0
    while i < len(words):
        collapsed = False
        remaining = len(words) - i
        # Smallest k first — finds the true period of the repetition.
        for k in range(1, max_phrase_words + 1):
            min_reps = _min_repeats_for_phrase_size(k)
            if remaining < k * min_reps:
                # Not enough tokens left to satisfy min_reps at this k.
                # Larger k can only need more tokens, so stop here.
                break
            phrase = words[i:i + k]
            count = 1
            j = i + k
            while j + k <= len(words) and words[j:j + k] == phrase:
                count += 1
                j += k
            if count >= min_reps:
                result.extend(phrase)
                i = j
                collapsed = True
                break
        if not collapsed:
            result.append(words[i])
            i += 1
    return ' '.join(result)


def collapse_repetition_hallucinations(text):
    """Strip stuck-loop hallucinations (phrase + character-run) from
    a transcription. Returns the cleaned text. Safe to call on any
    transcriber output; preserves text without obvious hallucinations
    unchanged.
    """
    if not text:
        return text
    text = _collapse_char_runs(text)
    text = _collapse_phrase_repetitions(text)
    return text


# Groq's `verbose_json` gives us the detected language. Normalise here so
# downstream checks see stable ISO-639-1 codes regardless of whether the
# API returned "he" or "hebrew" or "he-IL".
_LANGUAGE_NAME_TO_CODE = {
    "hebrew": "he",
    "english": "en",
    "arabic": "ar",
    "french": "fr",
    "russian": "ru",
    "spanish": "es",
    "german": "de",
    "italian": "it",
    "portuguese": "pt",
    "dutch": "nl",
    "polish": "pl",
    "turkish": "tr",
    "persian": "fa",
    "farsi": "fa",
    "urdu": "ur",
    "yiddish": "yi",
    "romanian": "ro",
    "ukrainian": "uk",
}


def _normalise_lang_code(raw):
    """Return a lowercase ISO-639-1 code. Accepts codes, names, or BCP-47 tags."""
    if not raw:
        return ""
    val = str(raw).strip().lower()
    if val in _LANGUAGE_NAME_TO_CODE:
        return _LANGUAGE_NAME_TO_CODE[val]
    return val.split("-", 1)[0] if "-" in val else val


def _weighted_mean_logprob(segments):
    """Duration-weighted mean of Whisper's per-segment avg_logprob.

    `verbose_json` returns avg_logprob per segment only (no top-level
    aggregate). Weighting by duration stops short noisy segments from
    dominating long clean ones. Returns None if nothing usable.
    """
    if not segments:
        return None
    total_dur = 0.0
    weighted_sum = 0.0
    unweighted = []
    for s in segments:
        try:
            lp = s.get("avg_logprob")
            if lp is None:
                continue
            lp = float(lp)
            start = float(s.get("start") or 0)
            end = float(s.get("end") or 0)
            dur = max(0.0, end - start)
            if dur > 0:
                weighted_sum += lp * dur
                total_dur += dur
            unweighted.append(lp)
        except (TypeError, ValueError):
            continue
    if total_dur > 0:
        return weighted_sum / total_dur
    if unweighted:
        return sum(unweighted) / len(unweighted)
    return None


