    def _meeting_transcribe_display(self, model_key):
        """Friendly transcription-engine name for the status card. Falls back to
        the raw key so a new/unknown model still shows something meaningful."""
        return self._MEETING_TRANSCRIBE_NAMES.get(model_key, model_key)

    def _resolve_meeting_model(self, key=None):
        """Get (transcriber, language_hint, is_diarized) for the configured
        meeting model. Caches instances per key. Returns (None, None, False)
        if the model can't be activated (missing API key, load error, etc.).
        """
        if key is None:
            key = self.config.get("meeting_model", "local_hebrew_turbo")
        cached = self._meeting_xcribers.get(key)
        if cached is not None:
            return cached
        triple = self._build_meeting_transcriber(key)
        if triple[0] is not None:
            self._meeting_xcribers[key] = triple
        return triple

    def _diarize_bundle_dir(self):
        """Return a ready OFFLINE pyannote bundle dir (a self-contained HF cache)
        or "". Priority: an explicit config path, else the default
        <base>/diarization_models when it holds a populated 'hub' cache. When one
        exists, diarization runs with NO network and NO HF token — which is what
        lets the weights ship inside a product (end users never touch HuggingFace)."""
        explicit = (self.config.get("diarize_models_dir", "") or "").strip()
        if explicit:
            return explicit if os.path.isdir(explicit) else ""
        default = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                               "diarization_models")
        hub = os.path.join(default, "hub")
        try:
            if os.path.isdir(hub) and os.listdir(hub):
                return default
        except OSError:
            pass
        return ""

    def _download_diarization_model(self):
        """One-time: fetch the pyannote weights into a local BUNDLE dir (default
        <base>/diarization_models) using the configured HF token. Afterwards the
        app diarizes fully OFFLINE, and that folder can be shipped with a product
        so end users need no token. Requires the token + accepted model terms."""
        hf = (self.config.get("hf_token", "") or "").strip() or bundled_hf_token()
        if not hf:
            self.overlay.show_error("Set a HuggingFace token first")
            self._set_hf_token()
            return
        base_dir = os.path.dirname(os.path.abspath(__file__))
        interp = find_python_interpreter()
        script = os.path.join(base_dir, "diarize_local.py")
        if interp is None or not os.path.exists(script):
            self.overlay.show_error("Diarization script unavailable")
            return
        target = (self.config.get("diarize_models_dir", "") or "").strip() \
            or os.path.join(base_dir, "diarization_models")

        def worker():
            import subprocess
            import tempfile
            try:
                os.makedirs(target, exist_ok=True)
            except Exception as e:
                self.overlay.show_error("Cannot create %s: %s" % (target, e))
                return
            self.overlay.show("  ⬇  Downloading diarization model (one-time, ~GB)…  ",
                               bg_color="#1e64c8", duration=4000)
            env = os.environ.copy()
            env["PYTHONUTF8"] = "1"
            env["PYTHONIOENCODING"] = "utf-8"
            env["HF_TOKEN"] = hf
            env["HUGGING_FACE_HUB_TOKEN"] = hf
            fd, outp = tempfile.mkstemp(suffix=".json", prefix="wt_diardl_")
            os.close(fd)
            # Token rides ONLY in env (HF_TOKEN above) - argv is visible to any
            # same-user process via the process list, env of a child is not.
            args = [interp, "-X", "utf8", script, "--download", "--models-dir", target,
                    "--model", self.config.get("diarize_local_model",
                                               "pyannote/speaker-diarization-community-1"),
                    "--out", outp]
            flags = 0x08000000  # CREATE_NO_WINDOW
            try:
                subprocess.run(args, env=env, creationflags=flags, timeout=3600,
                               stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
                data = {}
                try:
                    with open(outp, encoding="utf-8") as f:
                        data = json.load(f)
                finally:
                    try:
                        os.remove(outp)
                    except Exception:
                        pass
                if data.get("ok"):
                    log.info("Diarization model bundled at %s (%s)",
                             target, data.get("used_model"))
                    self.overlay.show("  ✓  Diarization model ready — runs offline now  ",
                                       bg_color="#1a7a3a", duration=4000)
                else:
                    self.overlay.show_error("Download failed: "
                                            + (data.get("error", "?")[:80]))
            except subprocess.TimeoutExpired:
                self.overlay.show_error("Model download timed out")
            except Exception as e:
                self.overlay.show_error("Download failed: %s" % str(e)[:80])

        threading.Thread(target=worker, daemon=True).start()

    # --- Turn-merge tuning for LOCAL (pyannote) diarization ---
    # Measured on real meetings (2026-08-12, a 2-spk and a 4-spk 5-min slice):
    # raw pyannote emits ~2x the turns AssemblyAI does — the same speaker gets
    # split at every breath, and sub-2s fragments then transcribe badly for
    # lack of context ("שהיא מתה דת"-grade gibberish from ivrit). Merging
    # same-speaker turns across small gaps (and across sub-second backchannels
    # like "כן"/"אה" from others) brings the turn shape to AssemblyAI-like
    # blocks while staying 100% local. The AssemblyAI path is untouched (its
    # API already returns merged utterances).
    _DIAR_MERGE_GAP_MS = 3000        # max silence between same-speaker turns
    _DIAR_MERGE_INTERJECT_MS = 1000  # other-speaker turn up to this long doesn't block
    _DIAR_MERGE_TURN_MAX_MS = 45000  # merged-turn cap: the proven 45s ivrit envelope
    _DIAR_MERGE_LOOKBACK = 3         # walk back over at most this many interjections

    def _merge_diarized_turns(self, utterances):
        """Merge pyannote's over-segmented turns into transcription-friendly
        blocks: consecutive same-speaker turns whose gap is ≤ GAP_MS become one
        turn, including across ≤ INTERJECT_MS backchannels from other speakers
        (the backchannel keeps its own turn — same shape AssemblyAI produces;
        its audio is inside the merged slice, which is exactly what makes the
        long re-transcription coherent). Merged turns are capped at TURN_MAX_MS
        so slices stay inside the proven 45s envelope. Input/output: AssemblyAI-
        shaped dicts with start/end in MILLISECONDS, sorted by start."""
        if not utterances:
            return utterances
        out = []
        for u in sorted(utterances, key=lambda x: float(x.get("start") or 0)):
            u = dict(u)
            target = None
            walked = 0
            for prev in reversed(out):
                if prev.get("speaker") == u.get("speaker"):
                    target = prev
                    break
                dur = float(prev.get("end") or 0) - float(prev.get("start") or 0)
                if dur <= self._DIAR_MERGE_INTERJECT_MS and walked < self._DIAR_MERGE_LOOKBACK:
                    walked += 1
                    continue
                break  # a real turn from another speaker blocks the merge
            if target is not None:
                gap = float(u.get("start") or 0) - float(target.get("end") or 0)
                span = float(u.get("end") or 0) - float(target.get("start") or 0)
                if gap <= self._DIAR_MERGE_GAP_MS and span <= self._DIAR_MERGE_TURN_MAX_MS:
                    target["end"] = max(float(target.get("end") or 0),
                                        float(u.get("end") or 0))
                    continue
            out.append(u)
        return out

    def _run_local_diarization(self, wav_path, on_status=None):
        """Run pyannote (diarize_local.py subprocess) on the meeting WAV and
        return AssemblyAI-shaped utterances [{speaker,start,end,text:""}] with
        start/end in MILLISECONDS. Diarization ONLY — the caller then transcribes
        each turn with the local ivrit.ai model (_rerun_utterances). Raises
        RuntimeError with a user-facing message on any failure (pyannote missing,
        HF token / model-terms, diarization error)."""
        import subprocess
        import tempfile
        base_dir = os.path.dirname(os.path.abspath(__file__))
        interp = find_python_interpreter()
        script = os.path.join(base_dir, "diarize_local.py")
        if interp is None or not os.path.exists(script):
            raise RuntimeError("Local diarization unavailable (no interpreter / script)")
        bundle = self._diarize_bundle_dir()
        if on_status:
            try:
                on_status("loading pyannote (bundled)…" if bundle else "loading pyannote…")
            except Exception:
                pass
        env = os.environ.copy()
        env["PYTHONUTF8"] = "1"
        env["PYTHONIOENCODING"] = "utf-8"
        # Token precedence: user's own config, then the shipped fallback file
        # (bundled_hf_token). Ignored entirely when the offline bundle is present
        # (diarize_local.py forces HF_HUB_OFFLINE with --models-dir).
        hf = (self.config.get("hf_token", "") or "").strip() or bundled_hf_token()
        if hf:
            env["HF_TOKEN"] = hf
            env["HUGGING_FACE_HUB_TOKEN"] = hf
        fd, out_path = tempfile.mkstemp(suffix=".json", prefix="wt_diar_")
        os.close(fd)
        # Token rides ONLY in env (HF_TOKEN above), never on the command line.
        args = [interp, "-X", "utf8", script, wav_path, "--out", out_path,
                "--model", self.config.get("diarize_local_model",
                                           "pyannote/speaker-diarization-community-1"),
                "--device", ("cpu" if self.config.get("whisper_device") == "cpu" else "auto")]
        if bundle:
            # Offline bundle present → load from it, no network / no HF token.
            args += ["--models-dir", bundle]
        flags = 0x08000000  # CREATE_NO_WINDOW
        try:
            # First run downloads model weights (can be minutes) → 1h ceiling.
            proc = subprocess.run(args, env=env, creationflags=flags, timeout=3600,
                                  stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
            try:
                with open(out_path, encoding="utf-8") as f:
                    data = json.load(f)
            except Exception:
                tail = ""
                try:
                    tail = (proc.stderr or b"").decode("utf-8", "replace").strip().splitlines()[-1]
                except Exception:
                    pass
                raise RuntimeError("Diarization produced no result "
                                   + ("(%s)" % tail[:120] if tail else ""))
        except subprocess.TimeoutExpired:
            raise RuntimeError("Local diarization timed out")
        finally:
            try:
                os.remove(out_path)
            except Exception:
                pass
        if not data.get("ok"):
            hint = data.get("hint")
            raise RuntimeError((data.get("error") or "diarization failed")
                               + (" — " + hint if hint else ""))
        utts = data.get("utterances") or []
        log.info("Local diarization: %d speakers, %d turns (model=%s, device=%s)",
                 data.get("num_speakers", 0), len(utts),
                 data.get("used_model"), data.get("device"))
        if not utts:
            raise RuntimeError("No speakers detected in the recording")
        merged = self._merge_diarized_turns(utts)
        if len(merged) != len(utts):
            log.info("Local diarization: merged %d raw turns → %d blocks",
                     len(utts), len(merged))
        utts = merged
        if on_status:
            try:
                on_status("%d speakers · %d turns" % (data.get("num_speakers", 0), len(utts)))
            except Exception:
                pass
        # Speaker naming: per-cluster voiceprints ride along (may be {}).
        return utts, (data.get("speaker_embeddings") or {})

    def _ensure_remote_transcriber(self):
        """Build (once) + return the WhisperLive serve-mode transcriber for the
        configured remote_server_url, or None if no URL is set. Shared by the
        dictation backend switch and the remote_hebrew_turbo meeting model."""
        url = (self.config.get("remote_server_url") or "").strip()
        if not url:
            return None
        if self._remote_transcriber is None:
            self._remote_transcriber = RemoteTranscriber(
                url=url, token=self.config.get("remote_server_token", ""),
                allow_insecure_ws=bool(self.config.get("remote_allow_insecure_ws")))
            self._remote_transcriber.custom_vocabulary = \
                self._composed_vocabulary()
        return self._remote_transcriber

    def _ensure_gemini_transcriber(self):
        """Build (once) + return the Gemini Transcribe client for the configured
        gemini_api_key, or None if no key is set. Shared by the gemini_transcribe
        (chunked) and gemini_diarize (whole-file) meeting models."""
        key = (self.config.get("gemini_api_key") or "").strip()
        if not key:
            return None
        if self._gemini_transcriber is None:
            self._gemini_transcriber = GeminiTranscriber(
                api_key=key,
                language_codes=lang_pack.gemini_language_codes(self.config),
            )
            self._gemini_transcriber.custom_vocabulary = \
                self._composed_vocabulary()
        return self._gemini_transcriber

    def _build_meeting_transcriber(self, key):
        """Create + load the transcriber for a given meeting_model key.
        Loading happens here so the first meeting/file action takes the hit;
        cache is populated by _resolve_meeting_model on success.
        """
        cb = lambda m: log.info("Meeting transcriber: %s", m)

        if key in ("gemini_transcribe", "gemini_diarize"):
            # gemini_transcribe = chunked (live transcript, non-diarized, like
            # groq_turbo). gemini_diarize = whole-file speaker diarization via
            # _run_diarize_job's "gemini" backend (is_diarized=True). Both share
            # one client; language None => the he+en whitelist auto-detects
            # (a meeting is routinely mixed - pinning "he" drops English).
            t = self._ensure_gemini_transcriber()
            if t is None:
                log.warning("Meeting model %s requires gemini_api_key", key)
                return (None, None, False)
            try:
                if t.model is None:
                    t.load_model(callback=cb)
            except Exception as e:
                log.error("Meeting model %s load failed: %s", key, e)
                return (None, None, False)
            return (t, None, key == "gemini_diarize")

        if key == "remote_hebrew_turbo":
            # Chunked meeting transcribed on the home GPU (WhisperLive + ivrit.ai).
            # Each ~45s chunk streams to the server; the live transcript updates as
            # chunks return — mid-meeting peeking works exactly as with local.
            t = self._ensure_remote_transcriber()
            if t is None:
                log.warning("Meeting model remote_hebrew_turbo requires "
                            "remote_server_url — set the Home Server first")
                return (None, None, False)
            try:
                if t.model is None:
                    t.load_model(callback=cb)
            except Exception as e:
                log.error("Meeting model remote_hebrew_turbo load failed: %s", e)
                return (None, None, False)
            return (t, "he", False)

        if key in ("openai_gpt_transcribe", "openai_gpt4o", "openai_gpt4o_mini"):
            api_key = self.config.get("openai_api_key", "").strip()
            if not api_key:
                log.warning("Meeting model %s requires OpenAI API key", key)
                return (None, None, False)
            model_size = {
                "openai_gpt_transcribe": "gpt-transcribe",
                "openai_gpt4o": "gpt-4o-transcribe",
                "openai_gpt4o_mini": "gpt-4o-mini-transcribe",
            }[key]
            t = OpenAITranscriber(model_size=model_size, api_key=api_key)
            t.he_en_bias = bool(self.config.get("groq_he_en_bias", True))
            t.preferred_language = lang_pack.primary_language(self.config)
            t.custom_vocabulary = self._composed_vocabulary()
            try:
                t.load_model(callback=cb)
            except Exception as e:
                log.error("Meeting model %s load failed: %s", key, e)
                return (None, None, False)
            return (t, None, False)

        if key == "groq_turbo":
            # Reuse the main Groq transcriber if it already exists with the
            # right model, otherwise build a fresh one. Saves an extra
            # load_model call on the common case.
            if (self._groq_transcriber is not None
                    and self._groq_transcriber.model_size == "whisper-large-v3-turbo"
                    and self._groq_transcriber.model is not None):
                return (self._groq_transcriber, None, False)
            api_key = self.config.get("groq_api_key", "").strip()
            if not api_key:
                log.warning("Meeting model groq_turbo requires Groq API key")
                return (None, None, False)
            t = GroqTranscriber(model_size="whisper-large-v3-turbo", api_key=api_key)
            t.he_en_bias = bool(self.config.get("groq_he_en_bias", True))
            t.custom_vocabulary = self._composed_vocabulary()
            try:
                t.load_model(callback=cb)
            except Exception as e:
                log.error("Meeting model groq_turbo load failed: %s", e)
                return (None, None, False)
            return (t, None, False)

        if key in ("local_parakeet_english", "local_pyannote_parakeet"):
            # English Parakeet (2026-08). local_pyannote_parakeet = the SAME model,
            # but the meeting is DIARIZED locally (pyannote is language-agnostic;
            # per-turn ASR = Parakeet). Reuse the dictation-side instance when
            # it is the same model and already loaded.
            diarized = (key == "local_pyannote_parakeet")
            main = self._local_transcriber
            if (isinstance(main, ParakeetTranscriber)
                    and main.model is not None):
                return (main, "en", diarized)
            t = ParakeetTranscriber(
                device=self.config.get("parakeet_device", "cpu"))
            try:
                t.load_model(callback=cb)
            except Exception as e:
                log.error("Meeting model %s load failed: %s", key, e)
                return (None, None, False)
            return (t, "en", diarized)

        if key in ("local_hebrew_turbo", "local_english_distil", "local_pyannote_hebrew"):
            # local_pyannote_hebrew = the SAME ivrit.ai Hebrew Whisper, but the
            # meeting is DIARIZED locally (pyannote finds the speaker turns, then
            # this model transcribes each turn — see _run_diarize_job's local path).
            is_hebrew = key in ("local_hebrew_turbo", "local_pyannote_hebrew")
            diarized = (key == "local_pyannote_hebrew")
            model_size = ("ivrit-ai/whisper-large-v3-turbo-ct2"
                           if is_hebrew else "distil-large-v3")
            language = "he" if is_hebrew else "en"

            def _local(size):
                """Build (or reuse an already-loaded instance of) a local
                model — reuse saves ~500MB-1.5GB of duplication. Looks
                THROUGH a dictation-side router to its children."""
                main = self._local_transcriber
                cands = ([main.he, main.general]
                         if isinstance(main, BilingualRouterTranscriber)
                         else [main])
                for c in cands:
                    if (c is not None and getattr(c, "model_size", None) == size
                            and c.model is not None):
                        return c
                t = FasterWhisperTranscriber(
                    model_size=size,
                    cpu_threads=self.config.get("cpu_threads", 16),
                    device=self.config.get("whisper_device", "auto"),
                    compute_type=self.config.get("cuda_compute_type"),
                )
                t.custom_vocabulary = self._composed_vocabulary()
                return t

            # Bilingual auto (default): wrap the Hebrew model in the router so
            # every chunk / diarized turn / file is language-detected and en
            # segments go to the general model instead of coming out as
            # phonetic-Hebrew gibberish. language=None → the router decides.
            if is_hebrew and bool(self.config.get("meeting_bilingual_auto", True)):
                # If dictation already runs the same router, share it whole —
                # one pair of models serves press-to-talk AND meetings.
                main = self._local_transcriber
                if (isinstance(main, BilingualRouterTranscriber)
                        and main.he.model_size == model_size
                        and main.model is not None):
                    return (main, None, diarized)
                router = BilingualRouterTranscriber(
                    he_transcriber=_local(model_size),
                    general_transcriber=_local(
                        BilingualRouterTranscriber.GENERAL_MODEL),
                    en_transcriber=self._router_en_child(),
                    primary=lang_pack.primary_language(self.config),
                )
                router.custom_vocabulary = \
                    self._composed_vocabulary()
                try:
                    router.load_model(callback=cb)
                except Exception as e:
                    log.error("Meeting model %s (bilingual) load failed: %s",
                              key, e)
                    return (None, None, False)
                return (router, None, diarized)

            t = _local(model_size)
            if t.model is None:
                try:
                    t.load_model(callback=cb)
                except Exception as e:
                    log.error("Meeting model %s load failed: %s", key, e)
                    return (None, None, False)
            return (t, language, diarized)

        if key in ("assemblyai_universal_2", "assemblyai_diarize_only",
                   "assemblyai_local_hebrew"):
            # All three use the SAME AssemblyAI diarized path. They differ only
            # in WHICH model (if any) re-transcribes each utterance for better
            # text — decided at meeting start (diarize_enhance_model), NOT here:
            #   assemblyai_universal_2  → gpt-4o     assemblyai_local_hebrew → HE local
            #   assemblyai_diarize_only → none (speakers only)
            api_key = self.config.get("assemblyai_api_key", "").strip()
            if not api_key:
                log.warning("Meeting model %s requires AssemblyAI API key", key)
                return (None, None, False)
            if self._assemblyai_transcriber is None:
                self._assemblyai_transcriber = AssemblyAITranscriber(api_key=api_key)
            return (self._assemblyai_transcriber, None, True)

        log.warning("Unknown meeting_model key %r — no-op", key)
        return (None, None, False)

    def _file_model_key(self):
        """Effective model key for Transcribe File."""
        return (self.config.get("file_transcribe_model", "") or "").strip() \
            or self.config.get("meeting_model", "local_hebrew_turbo")

    def _file_model_label(self):
        """Human label for the effective file model (shown on the menu action)."""
        key = self._file_model_key()
        for label, k, _req in self._MEETING_MODELS:
            if k == key:
                return label.strip()
        return key

    def _set_file_transcribe_model(self, key):
        """Persist the Transcribe File model. "" = follow the meeting model."""
        if key == self.config.get("file_transcribe_model", ""):
            return
        self.config["file_transcribe_model"] = key
        save_config(self.config)
        log.info("File transcribe model: %s", key or "(follow meeting model)")
        try:
            if self.tray_icon:
                self.tray_icon.update_menu()
        except Exception:
            pass

    def _set_meeting_model(self, key):
        """Persist a new meeting model. Cached transcribers stay until
        the user actually triggers a meeting / file transcribe."""
        if key == self.config.get("meeting_model"):
            return
        self.config["meeting_model"] = key
        save_config(self.config)
        log.info("Meeting model changed to: %s", key)
        try:
            if self.tray_icon:
                self.tray_icon.update_menu()
        except Exception:
            pass

    @staticmethod
    def _ollama_has(model, pulled):
        """True if `model` (e.g. 'gemma4:31b') is in the pulled-tag set, which
        carry a ':tag' suffix (Ollama defaults missing tags to ':latest').
        Static: called as self._ollama_has(model, pulled) - without the
        decorator `self` was bound to `model` and it raised "takes 2 positional
        arguments but 3 were given" whenever a local summary model was checked."""
        base = model.split(":")[0]
        return any(t == model or t.split(":")[0] == base for t in pulled)

    def _ollama_pulled(self):
        """Set of locally-pulled Ollama model tags, or None if Ollama isn't
        reachable. Cached ~10s so opening the submenu stays snappy."""
        now = time.time()
        cache = getattr(self, "_ollama_cache", None)
        if cache and now - cache[0] < 10:
            return cache[1]
        result = None
        try:
            import requests
            r = requests.get("http://localhost:11434/api/tags", timeout=1.0)
            if r.status_code == 200:
                result = {m.get("name", "") for m in r.json().get("models", [])}
        except Exception:
            result = None
        self._ollama_cache = (now, result)
        return result

    def _set_summary_model(self, model, base_url):
        """Persist the Meeting Summary Module choice and rebuild the summary
        cleaner lazily. For a local model, give immediate feedback if Ollama
        isn't ready (the choice still persists)."""
        if (model == self.config.get("summary_model")
                and (base_url or "") == self.config.get("summary_base_url", "")):
            return
        self.config["summary_model"] = model
        self.config["summary_base_url"] = base_url or ""
        save_config(self.config)
        self._summary_cleaner = None  # rebuilt on next summary with the new model
        log.info("Summary model → %s (%s)", model, base_url or "OpenAI cloud")
        if model == "off":
            self._notify_summary("AI summaries are OFF - meetings save a "
                                 "transcript only")
            try:
                if self.tray_icon:
                    self.tray_icon.update_menu()
            except Exception:
                pass
            return
        if _is_gemini_url(base_url):  # free Gemini — prompt for the key if missing
            if not (self.config.get("gemini_api_key", "") or "").strip():
                self._notify_summary("Enter a FREE Gemini key (Google AI Studio) to use it")
                self._set_gemini_api_key()
            else:
                self._notify_summary("Meeting summaries now use Gemini 3.7 Flash (free)")
        elif base_url:  # local — verify Ollama + the pull, warn (but keep) if not
            pulled = self._ollama_pulled()
            if pulled is None:
                self._notify_summary("Ollama isn't running — start it, then: "
                                     f"ollama pull {model}")
            elif not self._ollama_has(model, pulled):
                self._notify_summary(f"Model not pulled yet — run: ollama pull {model}")
            else:
                self._notify_summary(f"Meeting summaries now use {model} (local)")
        else:
            self._notify_summary("Meeting summaries now use ChatGPT (cloud)")
        try:
            if self.tray_icon:
                self.tray_icon.update_menu()
        except Exception:
            pass

    def _notify_summary(self, msg):
        """Best-effort user feedback for the Meeting Summary Module (tray balloon
        + log). A balloon persists longer than the overlay toast — better for an
        instructional 'ollama pull …' message."""
        log.info("Meeting Summary Module: %s", msg)
        try:
            if self.tray_icon:
                self.tray_icon.notify(msg, "Meeting Summary Module")
        except Exception:
            pass

    def _toggle_translate_mode(self):
        enabling = not self.config.get("translate_mode", False)
        self.config["translate_mode"] = enabling
        log.info("Translate mode: %s", "ON" if enabling else "OFF")

        if enabling:
            # Save the current (non-translate) model so we can restore it later
            current = self.config.get("model_size", "")
            if current != "large-v3":
                self.config["model_before_translate"] = current
            save_config(self.config)
            # Switch to large-v3 (only model that reliably translates)
            if current != "large-v3":
                log.info("Switching to General Large for translation")
                self._set_model("large-v3")
        else:
            # Restore previous model, or default to Hebrew Turbo
            previous = self.config.get("model_before_translate") or "ivrit-ai/whisper-large-v3-turbo-ct2"
            save_config(self.config)
            if self.config.get("model_size") != previous:
                log.info("Translate mode off: restoring model %s", previous)
                self._set_model(previous)

    def _set_language(self, lang):
        self.config["language"] = lang
        save_config(self.config)
        log.info("Language set to: %s", lang)

    @staticmethod
    def _compose_source(mic, sysaudio):
        """(mic, system) booleans → recording_source string."""
        if mic and sysaudio:
            return "both"
        if sysaudio:
            return "stereo_mix"
        return "microphone"

    def _apply_source_change(self):
        """Persist + log a recording_source change and refresh the menu. Clears
        stale silent-capture evidence (the next recording uses a new source)."""
        save_config(self.config)
        log.info("Recording source → %s (mic_idx=%s, loop_idx=%s)",
                 self.config["recording_source"],
                 self.config.get("input_device_index"),
                 self.config.get("loopback_device_index"))
        try:
            self._reset_silent_state()
        except Exception:
            pass
        try:
            if self.tray_icon:
                self.tray_icon.update_menu()
        except Exception:
            pass

    def _toggle_record_mic(self):
        """Top-level checkbox: record my microphone (my side). Default on."""
        src = self.config.get("recording_source", "microphone")
        mic_on = src in ("microphone", "both")
        sys_on = src in ("stereo_mix", "both")
        if mic_on and not sys_on:
            self.overlay.show_error("Keep at least one audio source")
            return
        self.config["recording_source"] = self._compose_source(not mic_on, sys_on)
        self._apply_source_change()

    def _toggle_record_system(self):
        """Top-level checkbox: also record system audio (the other side)."""
        if not LoopbackRecorder.is_available():
            self.overlay.show_error("System audio capture isn't available")
            return
        src = self.config.get("recording_source", "microphone")
        mic_on = src in ("microphone", "both")
        sys_on = src in ("stereo_mix", "both")
        if sys_on and not mic_on:
            self.overlay.show_error("Keep at least one audio source")
            return
        self.config["recording_source"] = self._compose_source(mic_on, not sys_on)
        self._apply_source_change()

    def _toggle_mic_device(self, device_idx):
        """Click handler for a mic device: toggle if same, switch if different."""
        source = self.config.get("recording_source", "microphone")
        current_idx = self.config.get("input_device_index")
        mic_on = source in ("microphone", "both")

        if mic_on and current_idx == device_idx:
            # Uncheck → disable mic category
            if source == "both":
                self.config["recording_source"] = "stereo_mix"
            else:
                # mic-only; disabling would leave no source
                self.overlay.show_error("Must keep at least one audio input")
                return
        else:
            # Check this mic (either a new device or re-enabling mic)
            self.config["input_device_index"] = device_idx
            try:
                self.recorder.input_device_index = device_idx
            except Exception:
                pass
            if source == "stereo_mix":
                self.config["recording_source"] = "both"
            elif not mic_on:
                self.config["recording_source"] = "microphone"
            # else already 'microphone' or 'both'; just swapped the device
        save_config(self.config)
        log.info("Audio input changed: source=%s, mic_idx=%s, loop_idx=%s",
                 self.config["recording_source"],
                 self.config.get("input_device_index"),
                 self.config.get("loopback_device_index"))
        # Clear silent-capture state. The next recording uses a different
        # mic; any prior "silent" hits were against the OLD device, and
        # are stale evidence — counting them toward the 2-strike auto-
        # restart threshold causes the app to spuriously self-restart
        # while the user is in the middle of switching mics.
        self._reset_silent_state()

    def _set_meeting_mic_device(self, device_idx):
        """Settings: pick the DEDICATED meeting mic (None = same as the
        dictation mic). Radio semantics - no toggle-off, 'Same as dictation
        mic' is the off row. Applies from the NEXT meeting; a running
        meeting keeps the recorder it opened."""
        self.config["meeting_input_device_index"] = device_idx
        save_config(self.config)
        log.info("Meeting mic set: %s",
                 "same as dictation" if device_idx is None else device_idx)

    def _toggle_loopback_device(self, device_idx):
        """Click handler for a system audio device: toggle if same, switch if different."""
        source = self.config.get("recording_source", "microphone")
        current_idx = self.config.get("loopback_device_index")
        loop_on = source in ("stereo_mix", "both")

        if loop_on and current_idx == device_idx:
            # Uncheck → disable system audio category
            if source == "both":
                self.config["recording_source"] = "microphone"
            else:
                # stereo_mix only; disabling leaves no source
                self.overlay.show_error("Must keep at least one audio input")
                return
            save_config(self.config)
        else:
            # Check this loopback (changes device; _set_loopback_device also saves)
            self._set_loopback_device(device_idx)
            if source == "microphone":
                self.config["recording_source"] = "both"
            elif not loop_on:
                self.config["recording_source"] = "stereo_mix"
            save_config(self.config)
        log.info("Audio input changed: source=%s, mic_idx=%s, loop_idx=%s",
                 self.config["recording_source"],
                 self.config.get("input_device_index"),
                 self.config.get("loopback_device_index"))
        # See _toggle_input_device above for rationale.
        self._reset_silent_state()

    def _reset_silent_state(self):
        """Clear the silent-capture counter and timestamp.

        Called whenever the user changes audio input. The 2-strike
        auto-restart logic in _handle_silent_capture is meant to detect
        a stuck PortAudio cache, NOT user-initiated input changes. If
        the user just switched mics, any previous silent captures were
        against a different device and shouldn't count.
        """
        self._consecutive_silent = 0
        self._last_silent_time = 0.0

    def _set_input_device(self, device_index):
        self.config["input_device_index"] = device_index
        save_config(self.config)
        # Update the current recorder instance so next recording uses it
        self.recorder.input_device_index = device_index
        # Mic device changed — clear silent counter so the next recording
        # starts with a clean slate (see _reset_silent_state for why).
        self._reset_silent_state()
        if device_index is None:
            log.info("Input device set to: System Default")
        else:
            log.info("Input device set to index: %s", device_index)

    def _set_paste_mode(self, mode):
        self.config["paste_mode"] = mode
        save_config(self.config)
        labels = {"auto_paste": "Auto-Paste", "clipboard_only": "Clipboard Only", "direct_type": "Direct Type"}
        log.info("Paste mode set to: %s", labels.get(mode, mode))

    def _set_recording_mode(self, mode):
        self.config["recording_mode"] = mode
        save_config(self.config)
        labels = {"hold": "Hold to Record", "toggle": "Toggle (press start/stop)"}
        log.info("Recording mode set to: %s", labels.get(mode, mode))

    # The language-flavored LOCAL model swaps the primary-language cascade
    # applies (chunked/diarized flavor preserved; cloud + AssemblyAI choices
    # are language-capable and left alone). remote is a Hebrew-only server.
    _LANG_DICTATION = {
        "en": {"ivrit-ai/whisper-large-v3-turbo-ct2": "parakeet-tdt-0.6b-v2",
               "ivrit-ai/whisper-large-v3-ct2": "parakeet-tdt-0.6b-v2"},
        "he": {"parakeet-tdt-0.6b-v2": "ivrit-ai/whisper-large-v3-turbo-ct2",
               "distil-large-v3": "ivrit-ai/whisper-large-v3-turbo-ct2"},
    }
    _LANG_MEETING = {
        "en": {"local_hebrew_turbo": "local_parakeet_english",
               "local_pyannote_hebrew": "local_pyannote_parakeet",
               "remote_hebrew_turbo": "local_parakeet_english"},
        "he": {"local_parakeet_english": "local_hebrew_turbo",
               "local_pyannote_parakeet": "local_pyannote_hebrew"},
    }

    def _set_primary_language(self, lang):
        """The ONE-CLICK language switch (2026-08). Stores primary_language and
        applies the language's recommended defaults - every change is listed
        in the returned message (shown as a toast), nothing else is touched,
        and each value remains individually changeable afterwards:
        - dictation model (LOCAL backend only - cloud serves both languages)
        - meeting + file models (language-flavored local keys, flavor kept)
        - the Groq/OpenAI he/en bias prompt (off for an English-primary user)
        - the router's English child -> Parakeet when switching to en
        Summary language follows automatically via summary_language="primary"."""
        if lang not in ("he", "en"):
            return (False, "Unknown language: %s" % lang)
        self.config["primary_language"] = lang
        changed = []
        pk_ok = (lang != "en") or self._parakeet_available()
        # dictation (local backend only)
        new_model = self._LANG_DICTATION[lang].get(self.config.get("model_size", ""))
        if not (new_model and pk_ok
                and self.config.get("transcription_backend", "local") == "local"):
            new_model = None
        # meeting + file models
        for ckey, label in (("meeting_model", "meetings"),
                            ("file_transcribe_model", "files")):
            new = self._LANG_MEETING[lang].get(self.config.get(ckey, "") or "")
            if new and pk_ok:
                self.config[ckey] = new
                changed.append("%s -> %s"
                               % (label, self._MEETING_TRANSCRIBE_NAMES.get(new, new)))
        # cloud he/en bias: targeted at a Hebrew-primary user; plain
        # auto-detect serves an English-primary one better.
        want_bias = (lang == "he")
        if bool(self.config.get("groq_he_en_bias", True)) != want_bias:
            self.config["groq_he_en_bias"] = want_bias
            for t in (self._groq_transcriber, self._openai_transcriber):
                if t is not None:
                    t.he_en_bias = want_bias
            changed.append("he/en bias " + ("on" if want_bias else "off"))
        if self._openai_transcriber is not None:
            self._openai_transcriber.preferred_language = lang
        # best English quality inside the router for an en-primary user
        if (lang == "en" and self._parakeet_available()
                and self.config.get("bilingual_english_model") != "parakeet"):
            self.config["bilingual_english_model"] = "parakeet"
            changed.append("router English model -> Parakeet")
        save_config(self.config)
        if new_model:
            changed.insert(0, "dictation -> " + MODELS.get(new_model, new_model))
            self._set_model(new_model)   # persists + reloads on its own thread
        log.info("Primary language set to %s (%s)", lang,
                 "; ".join(changed) if changed else "no model changes")
        return (True, ("Primary language: %s. " % ("Hebrew" if lang == "he" else "English"))
                + ("Applied: " + "; ".join(changed) if changed
                   else "Models unchanged."))

    def _set_summary_language(self, mode):
        """summary_language: primary / auto / he / en (see DEFAULT_CONFIG)."""
        if mode not in ("primary", "auto", "he", "en"):
            return (False, "Unknown summary language: %s" % mode)
        self.config["summary_language"] = mode
        save_config(self.config)
        log.info("Summary language set to: %s", mode)

    def _set_recording_source(self, source):
        if source in ("stereo_mix", "both") and self._loopback_recorder is None:
            self.overlay.show_error("Stereo Mix not available")
            return
        self.config["recording_source"] = source
        save_config(self.config)
        labels = {"microphone": "Microphone", "stereo_mix": "Stereo Mix", "both": "Both (Mic + Stereo Mix)"}
        log.info("Recording source set to: %s", labels.get(source, source))

    # (Mic + system-audio device selection now lives on the Settings -> Audio
    # page, driven by _settings_state's device lists + the toggle_* actions.)

    def _set_loopback_device(self, device_index):
        self.config["loopback_device_index"] = device_index
        save_config(self.config)
        # Reinitialize loopback recorder with the new device
        if LoopbackRecorder.is_available():
            loopback_info = LoopbackRecorder.find_loopback_device(device_index=device_index)
            if loopback_info:
                self._loopback_recorder = LoopbackRecorder(loopback_device_index=device_index)
                self._loopback_device_name = loopback_info.get("name", "System Audio")
                log.info("Loopback device set to: %s", self._loopback_device_name)
            else:
                self._loopback_recorder = None
                self._loopback_device_name = None
                log.warning("Selected loopback device not found")
        if device_index is None:
            log.info("Loopback device set to: System Default")
        else:
            log.info("Loopback device set to index: %s", device_index)

    def _set_streaming_mode(self, mode):
        self.config["streaming_mode"] = mode
        save_config(self.config)
        labels = {"off": "Off", "preview": "Preview", "live_dictation": "Live Dictation"}
        log.info("Streaming mode set to: %s", labels.get(mode, mode))

    # Model menu rows in display order (top → bottom).
    # Tuple shape: (label, model_size, backend, translate, openai_model)
    # `openai_model` is the openai_model config value to set; "" for non-OpenAI rows.
    # Order: OpenAI cloud (best) → Groq cloud → local fallbacks. OpenAI rows
    # are filtered out by _settings_tables (Models page) when no OpenAI key is set.
    # NOTE: the model_size on the cloud rows is the LOCAL FALLBACK used when the
    # cloud backend is unreachable. For a Hebrew-first user the fallback should
    # be the Hebrew-tuned model, not the generic multilingual one — so the
    # OpenAI row falls back to ivrit-ai (also lets the diarized 'Hebrew Local'
    # enhance reuse the already-loaded model instead of loading a second one).
    # LOCAL first (2026-08-29, Naor's ordering): the local models are the
    # product's identity and the app default; cloud follows, remote last.
    _MENU_MODELS_ORDERED = [
        ("Hebrew Turbo Local ⭐ (best local Hebrew)", "ivrit-ai/whisper-large-v3-turbo-ct2", "local", False, ""),
        ("English Parakeet Local ⭐ (best English)", "parakeet-tdt-0.6b-v2", "local", False, ""),
        ("English Distil Local", "distil-large-v3", "local", False, ""),
        ("General Turbo Local (multilingual · 99 languages)", "large-v3-turbo", "local", False, ""),
        ("OpenAI GPT transcribe", "ivrit-ai/whisper-large-v3-turbo-ct2", "openai", False, "gpt-transcribe"),
        ("OpenAI GPT-4o transcribe", "ivrit-ai/whisper-large-v3-turbo-ct2", "openai", False, "gpt-4o-transcribe"),
        ("Groq Whisper Large v3 Turbo", "large-v3-turbo", "groq", False, ""),
        ("Gemini 3.5 transcribe", "ivrit-ai/whisper-large-v3-turbo-ct2", "gemini", False, ""),
        ("Hebrew Turbo Remote", "ivrit-ai/whisper-large-v3-turbo-ct2", "remote", False, ""),
    ]

    def _set_model_backend_translate(self, model, backend, translate, openai_model=""):
        """Set model, backend, translate mode, and (for OpenAI) the OpenAI model
        atomically from the unified Model menu."""
        current_model = self.config.get("model_size")
        current_backend = self.config.get("transcription_backend", "local")
        current_translate = bool(self.config.get("translate_mode", False))
        current_openai_model = self.config.get("openai_model", "gpt-4o-transcribe")
        same_openai = (backend != "openai") or (current_openai_model == openai_model)
        if (current_model == model and current_backend == backend
                and current_translate == translate and same_openai):
            return
        # API-key guards
        if backend == "groq" and not self.config.get("groq_api_key", "").strip():
            log.warning("Groq selected but no API key — opening key dialog")
            self.overlay.show_error("Set Groq API key first")
            self._set_groq_api_key()
            return
        if backend == "openai" and not self.config.get("openai_api_key", "").strip():
            log.warning("OpenAI selected but no API key — opening key dialog")
            self.overlay.show_error("Set OpenAI API key first")
            self._set_openai_api_key()
            return
        if backend == "remote" and not (self.config.get("remote_server_url") or "").strip():
            log.warning("Remote selected but no server URL — opening dialog")
            self.overlay.show_error("Set the Home Server URL first")
            self._set_remote_server()
            return
        if backend == "gemini" and not (self.config.get("gemini_api_key") or "").strip():
            log.warning("Gemini selected but no API key — opening dialog")
            self.overlay.show_error("Set Gemini API key first")
            self._set_gemini_api_key()
            return
        # Update translate mode
        if current_translate != translate:
            self.config["translate_mode"] = translate
            save_config(self.config)
            log.info("Translate mode: %s", "ON" if translate else "OFF")
        # Update model_size (always — used for local fallback + language hint)
        if current_model != model:
            self._set_model(model)
        # If switching OpenAI sub-model, update config and the live transcriber
        if backend == "openai" and openai_model and current_openai_model != openai_model:
            self.config["openai_model"] = openai_model
            save_config(self.config)
            if self._openai_transcriber is not None:
                self._openai_transcriber.model_size = openai_model
            log.info("OpenAI model: %s", openai_model)
        # Then switch backend
        if current_backend != backend:
            self._set_backend(backend)

    def _whisper_device_label(self):
        """Short current-value label for the Device submenu title (so the picked
        device shows at a glance without opening the submenu)."""
        return {"auto": "Auto", "cuda": "GPU", "cpu": "CPU"}.get(
            self.config.get("whisper_device", "auto"), "Auto")

    def _set_whisper_device(self, dev):
        """Options → Models & Engine → Device radio. 'auto' (default) uses
        the NVIDIA GPU when present, else CPU — GPU-less machines need no
        setting at all. 'cpu' forces CPU: for machines whose GPU is weaker
        than their CPU (auto would still pick the GPU — it works, it's just
        slower). 'cuda' forces GPU. Rebuilds + reloads the local transcriber
        on the new device; the meeting/file transcriber cache is cleared so
        the next meeting rebuilds on it too."""
        if dev == self.config.get("whisper_device", "auto"):
            return
        # Same guards as a model switch: never swap the transcriber out from
        # under an in-flight capture.
        if (self.is_recording or self._compose_active or self._compose_instr_active
                or self._voice_ask_active):
            self.overlay.show_error("Finish the current recording first")
            return
        if self._is_meeting_active():
            self.overlay.show_error("Stop the meeting before switching device")
            return
        self.config["whisper_device"] = dev
        save_config(self.config)
        log.info("Whisper device set to: %s", dev)
        # Cached meeting/file transcribers were built on the OLD device —
        # drop them so _resolve_meeting_model rebuilds on the new one.
        self._meeting_xcribers.clear()
        self.model_loaded = False
        self._local_load_event.clear()
        self._local_transcriber = self._make_local_transcriber(
            self.config["model_size"])
        if self.config.get("transcription_backend", "local") == "local":
            self.transcriber = self._local_transcriber
        threading.Thread(target=self._load_model, daemon=True).start()

    def _set_model(self, model):
        if model != self.config["model_size"]:
            # Don't swap the transcriber out from under an in-flight capture:
            # do_transcribe reads self.transcriber at TRANSCRIBE time, so a
            # mid-recording switch on the local backend handed it a model=None
            # instance and the dictation was lost.
            if (self.is_recording or self._compose_active or self._compose_instr_active
                    or self._voice_ask_active):
                self.overlay.show_error("Finish the current recording first")
                return
            self.config["model_size"] = model
            save_config(self.config)
            self.model_loaded = False
            # New transcriber instance below — the event promises the OLD
            # instance is ready. Clear so fallback waits on the fresh load.
            self._local_load_event.clear()

            engine = self.config.get("engine", "faster_whisper")
            if engine == "openvino" and OpenVINOTranscriber.is_available():
                self._local_transcriber = OpenVINOTranscriber(
                    model_size=model,
                    cpu_threads=self.config["cpu_threads"],
                    device=self.config.get("openvino_device", "GPU"),
                )
            else:
                self._local_transcriber = self._make_local_transcriber(model)
            # Only replace self.transcriber if we're actually on the local backend.
            # If on Groq, keep Groq active — the local transcriber is only for fallback.
            backend = self.config.get("transcription_backend", "local")
            if backend == "local":
                self.transcriber = self._local_transcriber
            else:
                log.info("Model changed (language hint only) — staying on %s backend", backend)
            threading.Thread(target=self._load_model, daemon=True).start()
            log.info("Switching to model: %s", model)

    def _set_engine(self, engine, device=None):
        changed = False
        if engine != self.config.get("engine", "faster_whisper"):
            self.config["engine"] = engine
            changed = True
        if device and device != self.config.get("openvino_device"):
            self.config["openvino_device"] = device
            changed = True
        if not changed:
            return

        save_config(self.config)
        self.model_loaded = False

        if engine == "openvino":
            # Switch to an OpenVINO model if current model isn't one
            if self.config["model_size"] not in OPENVINO_MODELS:
                self.config["model_size"] = "OpenVINO/whisper-large-v3-int8-ov"
                save_config(self.config)
            self.transcriber = OpenVINOTranscriber(
                model_size=self.config["model_size"],
                cpu_threads=self.config["cpu_threads"],
                device=device or self.config.get("openvino_device", "GPU"),
            )
        else:
            # Switch back to faster-whisper
            if self.config["model_size"] in OPENVINO_MODELS:
                self.config["model_size"] = "ivrit-ai/whisper-large-v3-turbo-ct2"
                save_config(self.config)
            self.transcriber = FasterWhisperTranscriber(
                model_size=self.config["model_size"],
                cpu_threads=self.config["cpu_threads"],
                device=self.config.get("whisper_device", "auto"),
                compute_type=self.config.get("cuda_compute_type"),
            )

        threading.Thread(target=self._load_model, daemon=True).start()
        log.info("Switched engine to: %s (device: %s)", engine, device)

    def _toggle_auto_start(self):
        enabled = not is_auto_start_enabled()
        set_auto_start(enabled)
        # is_auto_start_enabled() is the source of truth (it checks the task);
        # reflect what actually got set in case task registration failed.
        actual = is_auto_start_enabled()
        self.config["auto_start"] = actual
        save_config(self.config)
        try:
            if actual:
                self.tray_icon.notify(
                    "Lia will start automatically at logon — elevated, "
                    "with no UAC prompt.", "Start with Windows: ON")
            else:
                self.tray_icon.notify("Auto-start disabled.", "Start with Windows: OFF")
        except Exception:
            pass
        try:
            self.tray_icon.update_menu()
        except Exception:
            pass

    def _migrate_legacy_autostart(self):
        """One-time: remove any orphaned pre-rebrand logon task ('WhisperType'
        after the first rename, 'Recap' after the rename to Lia) that would
        keep auto-starting the app under its old name, then re-sync the OS
        auto-start state to the configured intent. Runs elevated (the app has
        admin). Guarded by a config flag; if removal can't complete (e.g. a
        non-elevated run) the flag is NOT set so it retries next launch."""
        if self.config.get("_legacy_autostart_migrated_lia"):
            return
        try:
            _remove_legacy_startup_shortcuts()
        except Exception:
            pass
        try:
            # Re-assert the DECLARED intent FIRST, unconditionally: the rename
            # can leave a mechanism that EXISTS but points at a dead path, so
            # an is-enabled guard would wrongly skip the repair. set_auto_start
            # is idempotent and rewrites the mechanism at the CURRENT path.
            # Runs before the elevated-only task cleanup so a non-elevated
            # launch still repairs auto-start (the Run-key path needs no
            # admin). One-time by the flag below, so a mechanism the user
            # removed by hand OUTSIDE the app is resurrected at most once.
            resync_ok = True
            if self.config.get("auto_start"):
                try:
                    set_auto_start(True)
                    resync_ok = is_auto_start_enabled()
                except Exception as e:
                    resync_ok = False
                    log.warning("Auto-start re-sync error: %s", e)
                if resync_ok:
                    log.info("Auto-start re-asserted for the 'Lia' rename")
            tasks_dir = os.path.join(os.environ.get("SystemRoot", r"C:\Windows"),
                                     "System32", "Tasks")
            legacy = [n for n in _LEGACY_TASK_NAMES
                      if os.path.isfile(os.path.join(tasks_dir, n))]
            if legacy:
                import subprocess
                for n in legacy:
                    try:
                        subprocess.run(
                            ["powershell", "-NoProfile", "-Command",
                             "Unregister-ScheduledTask -TaskName '%s' -Confirm:$false "
                             "-ErrorAction SilentlyContinue" % n],
                            capture_output=True, text=True,
                            creationflags=0x08000000, timeout=30)
                    except Exception:
                        pass
                still = [n for n in legacy
                         if os.path.isfile(os.path.join(tasks_dir, n))]
                if still:
                    log.warning("Legacy auto-start task(s) still present (need "
                                "admin to remove): %s — retrying next launch",
                                ", ".join(still))
                    return  # don't set the flag; retry when elevated
                log.info("Removed orphaned legacy auto-start task(s): %s",
                         ", ".join(legacy))
            if not resync_ok:
                log.warning("Auto-start re-sync incomplete (Settings -> General "
                            "-> 'Start with Windows' re-toggles it) - "
                            "retrying next launch")
                return  # don't set the flag; the re-sync IS the retry
            self.config["_legacy_autostart_migrated_lia"] = True
            save_config(self.config)
        except Exception as e:
            log.warning("Legacy auto-start migration failed: %s", e)

    def _set_beep_device(self, device_index):
        """Change the output device used for the beep, then play a test beep on it.
        device_index can be: None (System Default), "off" (no beep), or int (specific device)."""
        self.config["beep_device_index"] = device_index
        save_config(self.config)
        if device_index == "off":
            log.info("Beep output: disabled")
            return  # No test beep when disabled
        if device_index is None:
            log.info("Beep output: System Default")
        else:
            log.info("Beep output set to device index %s", device_index)
        # Test beep on the new device
        threading.Thread(
            target=lambda: play_beep(device_index=device_index),
            daemon=True,
        ).start()

    def _play_done_beep(self):
        """Play the 'transcription done' beep, respecting play_sound and beep_device_index='off'."""
        if not self.config.get("play_sound", True):
            return
        device = self.config.get("beep_device_index")
        if device == "off":
            return
        play_beep(1000, 100, device_index=device)

    def _is_likely_hallucination(self, text, audio_rms, duration_sec):
        """Heuristic: post-transcription, decide whether the model invented
        words from near-silent audio.

        Whisper-family models are trained on YouTube + podcast captions
        and have a strong bias toward producing SOMETHING when handed
        audio. On a clip with only ambient noise (fans, breath, mouse
        clicks), gpt-4o-transcribe has been observed to produce short,
        slow, plausible Hebrew phrases like "למזלי", "כי בשנה", "אפשר
        להסביר" — none of which the user said.

        Three signals together flag a likely hallucination:
          - audio_rms in the borderline range (0.008-0.025): above the
            silent guard but below typical conversational speech (≥ 0.05)
          - text is short (< 50 chars): real utterances longer than that
            are almost always intentional
          - chars/sec < 4: real speech runs 8-15 chars/sec; well-below
            that on a clip without explicit pauses is suspicious
        """
        if not text:
            return False
        if duration_sec < 1.5:
            return False  # too short to judge by char rate
        cleaned = text.replace('‏', '').replace('‎', '').strip()
        if not cleaned or len(cleaned) >= 50:
            return False
        chars_per_sec = len(cleaned) / max(0.5, duration_sec)
        if audio_rms < 0.025 and chars_per_sec < 4.0:
            log.warning(
                "Likely hallucination: %d chars over %.1fs (%.1f chars/sec), "
                "audio peak RMS %.5f. Rejecting transcription %r.",
                len(cleaned), duration_sec, chars_per_sec, audio_rms, cleaned,
            )
            return True
        return False

    def _handle_silent_capture(self, duration_sec, rms):
        """Called when a recording came back silent (RMS below threshold).

        Two cases, depending on the active recorder:

        1) SubprocessAudioRecorder (the default since 2026-04).
           Each recording uses a FRESH Python subprocess with its own
           PortAudio init, so the stale-WASAPI-handle bug that this
           handler was originally written for is structurally
           impossible. We just respawn the worker quietly and return.
           No overlay, no tray flash, no auto-restart — the user can
           tell from the live waveform whether their mic was captured
           (bars moved → audio; bars flat → silent).

        2) In-process AudioRecorder (frozen PyInstaller fallback).
           The classic flow still applies: the long-running process
           CAN end up with stuck PortAudio handles. We log, flash, and
           after 3 consecutive silents auto-restart the process.
        """
        now = time.time()
        if now - self._last_silent_time > 120:
            self._consecutive_silent = 0
        self._consecutive_silent += 1
        self._last_silent_time = now

        log.warning(
            "Silent audio detected (#%d): duration=%.1fs RMS=%.5f.",
            self._consecutive_silent, duration_sec, rms,
        )

        # Subprocess recorder path — quiet recovery, no UI noise, no restart.
        if isinstance(self.recorder, SubprocessAudioRecorder):
            try:
                self.recorder.respawn_after_stale()
            except Exception as e:
                log.warning("Worker respawn failed: %s", e)
            # Reset the tray icon and overlay back to idle. _stop_and_transcribe
            # set them to "processing" / "Transcribing..." before calling us;
            # without this the icon stays stuck on amber and the tooltip on
            # "Lia - Transcribing..." until the next recording
            # explicitly clobbers them. (User reported the tray as "stuck on
            # TRANSCRIBING" after a silent capture — this is why.)
            try:
                self.overlay.hide()
            except Exception:
                pass
            self._refresh_tray(update_menu=False)
            return

        # In-process AudioRecorder path — original behaviour with the
        # 3-consecutive auto-restart safety net.
        if self._consecutive_silent >= 3:
            log.warning("3 consecutive silent captures (in-process recorder) — "
                        "auto-restarting to fix stale PortAudio state")
            self._force_show_error_overlay(
                "🔄 Audio stack stuck — restarting Lia..."
            )
            self._flash_error_tray("Auto-restarting to fix audio...", duration_sec=5.0)
            threading.Thread(
                target=lambda: (time.sleep(1.5), self._restart_app("silent-audio")),
                daemon=True,
            ).start()

    def _force_show_error_overlay(self, msg):
        """Show an error overlay bypassing silent_mode.

        silent_mode is meant to suppress SUCCESS feedback (the waveform
        and 'Done' overlays) — but an error that blocks transcription is
        precisely what the user needs to see. Temporarily flip silent off,
        show, then flip it back.
        """
        try:
            self.overlay.silent = False
            self.overlay.show(f"  ⚠  {msg}  ",
                              bg_color="#6b0f1a", duration=3500)
        except Exception:
            pass
        finally:
            # Restore after a delay — we can't restore immediately because
            # the show command is queued for the Tk thread. Restore from
            # CONFIG (the source of truth), not a snapshot: two overlapping
            # error overlays used to snapshot each other's flipped state and
            # leave silent mode permanently off after an error burst.
            def _restore():
                time.sleep(4.0)
                self.overlay.silent = bool(self.config.get("silent_mode", False))
            threading.Thread(target=_restore, daemon=True).start()

    def _flash_error_tray(self, msg, duration_sec=3.0):
        """Briefly set the tray icon to the 'error' state, then restore to idle.

        This is the user feedback channel that works even when silent_mode is
        ON and beep is OFF — both of which the user has configured. Without
        this, a failed transcription produces ZERO visible signal: no overlay
        (silent_mode suppresses it), no beep (disabled), no paste (text was
        empty after hallucination-strip). The user would have no way to know
        the recording didn't produce usable output.

        The icon flashes red-X for `duration_sec`, then goes back to green-
        idle — but only if no new recording has started in the meantime
        (generation counter check prevents clobbering fresh state).
        """
        if not self.tray_icon:
            return
        my_gen = self._recording_generation
        try:
            self.tray_icon.icon = self._create_icon("error")
            self.tray_icon.title = f"Lia - {msg}"
        except Exception as e:
            log.warning("_flash_error_tray: setting error icon failed: %s", e)
            return

        def restore():
            time.sleep(duration_sec)
            # Only restore if this flash is still 'current' — a new recording
            # may have bumped generation, in which case the newer flow owns
            # the icon state and we must not clobber it.
            if self.tray_icon and my_gen == self._recording_generation:
                try:
                    self._refresh_tray(update_menu=False)
                except Exception:
                    pass

        threading.Thread(target=restore, daemon=True).start()

    def _toggle_he_en_bias(self):
        """Toggle the Hebrew/English bias prompt sent to Groq.
        ON  = Whisper sees a bilingual hint, less likely to detect French/Spanish/etc.
        OFF = no prompt, fastest possible response, full auto-detect over all languages."""
        new_value = not bool(self.config.get("groq_he_en_bias", True))
        self.config["groq_he_en_bias"] = new_value
        save_config(self.config)
        if self._groq_transcriber is not None:
            self._groq_transcriber.he_en_bias = new_value
        if self._openai_transcriber is not None:
            self._openai_transcriber.he_en_bias = new_value
        log.info("he/en bias: %s", "ON" if new_value else "OFF")

    # ----- AI Cleanup menu -----
    CLEANUP_MENU_STYLES = [
        ("Off — raw transcription", "off"),
        ("Spoken ⭐ — remove fillers + self-corrections, keep wording", "spoken"),
        ("Casual — typos + basic grammar (keeps fillers)", "casual"),
        ("Proofread — full spelling + grammar polish", "proofread"),
        ("Email polish — email-ready prose", "email"),
        ("Technical/Code — preserve tech terms", "code"),
    ]

    def _effective_cleanup_provider(self):
        """Which provider the cleanup pass will ACTUALLY run on — honors the
        explicit `cleanup_provider` preference ("auto"/"openai"/"groq"/"gemini")
        but falls back when the preferred provider's key is missing. Returns
        "openai" / "groq" / "gemini" / None. "auto" = OpenAI, else Groq, else
        Gemini (whichever key exists, in that order)."""
        pref = self.config.get("cleanup_provider", "auto")
        has_oa = bool((self.config.get("openai_api_key") or "").strip())
        has_gq = bool((self.config.get("groq_api_key") or "").strip())
        has_gm = bool((self.config.get("gemini_api_key") or "").strip())
        if pref == "openai" and has_oa:
            return "openai"
        if pref == "groq" and has_gq:
            return "groq"
        if pref == "gemini" and has_gm:
            return "gemini"
        if has_oa:
            return "openai"
        if has_gq:
            return "groq"
        if has_gm:
            return "gemini"
        return None

    def _make_cleanup_cleaner(self):
        """Build the AI-Cleanup LLM client for the effective provider (or None
        when no key is set). SINGLE source of truth — __init__, the Model
        picker, and the API-key dialogs all rebuild through here, so the
        provider preference is always respected and can't drift. Gemini reuses
        OpenAILLMCleaner against its OpenAI-compatible endpoint + own key."""
        prov = self._effective_cleanup_provider()
        if prov == "openai":
            return OpenAILLMCleaner(
                api_key=(self.config.get("openai_api_key") or "").strip(),
                model=self.config.get("cleanup_llm_model_openai", "gpt-5.6-luna"))
        if prov == "groq":
            return GroqLLMCleaner(
                api_key=(self.config.get("groq_api_key") or "").strip(),
                model=self.config.get("cleanup_llm_model", "llama-3.3-70b-versatile"))
        if prov == "gemini":
            return OpenAILLMCleaner(
                api_key=(self.config.get("gemini_api_key") or "").strip(),
                model=self.config.get("cleanup_llm_model_gemini", "gemini-3.5-flash-lite"),
                chat_url=GEMINI_CHAT_URL)
        return None

    def _cleanup_model_label(self):
        """Short label for the LLM the cleanup pass will actually run on —
        drives the dynamic 'AI Cleanup (<model>)' menu title. Reflects the
        EFFECTIVE provider (free Groq/Gemini vs a specific OpenAI model) so the
        user sees at a glance what runs, and that it's free."""
        prov = self._effective_cleanup_provider()
        if prov == "openai":
            return self.config.get("cleanup_llm_model_openai", "gpt-5.6-luna")
        if prov == "groq":
            return "Groq · free"
        if prov == "gemini":
            return "Gemini · free"
        return "no key"

    # OpenAI cleanup models offered in the picker. gpt-5.6-luna is the light 5.6 tier
    # and the DEFAULT ⭐ — measured ~0.7s warm on the user's Hebrew dictation with
    # reasoning_tokens=0 for cleanup (no visible thinking), so it's fast enough to be
    # the only "light" OpenAI row. sol/terra are the stronger 5.6 models for when
    # quality matters. gpt-5.1 and gpt-4.1 were dropped 2026-08-15 (redundant with
    # luna, which is as fast, and with the free Gemini/Groq paths); gpt-4o dropped
    # earlier. gpt-5.x shaping (max_completion_tokens, no temperature) is in
    # OpenAILLMCleaner.clean().
    CLEANUP_OPENAI_MODELS = [
        ("OpenAI ChatGPT 5.6 Luna - light, fast ⭐", "gpt-5.6-luna"),
        ("OpenAI ChatGPT 5.6 Sol - strongest", "gpt-5.6-sol"),
        ("OpenAI ChatGPT 5.6 Terra - strongest (alt)", "gpt-5.6-terra"),
    ]

    # Gemini cleanup models (FREE tier, own gemini_api_key, via the OpenAI-compat
    # endpoint). Flash-Lite is the fastest AND the most accurate for this job, so
    # it's the only row: benchmarked 2026-08-15 on real Hebrew+English dictation
    # (spoken style), Flash-Lite ran ~0.64s warm and correctly resolved the
    # self-correction, while gemini-3.7-flash took ~3.7s (one 12s spike) and
    # returned the text UNCLEANED — its mandatory thinking is an asset for
    # summaries but dead weight on a short per-dictation pass, so 3.7 was dropped
    # here (it stays in the SUMMARY + meetings pickers). No gemini-3.7-flash-lite
    # exists (verified 2026-08-15). Free tier RATE LIMIT ~15 req/min → a burst of
    # dictations can 429; clean() backs off and falls back to raw text.
    CLEANUP_GEMINI_MODELS = [
        ("✨  Gemini 3.5 Flash-Lite (free, fastest)", "gemini-3.5-flash-lite"),
    ]

    def _set_cleanup_provider_model(self, provider, model=None):
        """Pin the cleanup provider (+ the model for that provider), persist,
        and hot-rebuild the live cleaner so the change applies without a
        restart."""
        self.config["cleanup_provider"] = provider
        if provider == "openai" and model:
            self.config["cleanup_llm_model_openai"] = model
        elif provider == "groq" and model:
            self.config["cleanup_llm_model"] = model
        elif provider == "gemini" and model:
            self.config["cleanup_llm_model_gemini"] = model
        save_config(self.config)
        self._llm_cleaner = self._make_cleanup_cleaner()
        label = model or provider
        log.info("Cleanup provider set to %s (%s)", provider, label)
        try:
            self.overlay.show(f"  ✨  Cleanup: {label}  ",
                              bg_color="#1e64c8", duration=1500)
        except Exception:
            pass

    def _set_cleanup_style(self, style):
        """Change cleanup style + persist."""
        if style == self.config.get("cleanup_style"):
            return
        self.config["cleanup_style"] = style
        save_config(self.config)
        log.info("Cleanup style: %s", style)

    def _toggle_clipboard_auto_restore(self):
        """Flip the 'put the user's previous clipboard back after a paste' setting."""
        new_val = not bool(self.config.get("clipboard_auto_restore", True))
        self.config["clipboard_auto_restore"] = new_val
        save_config(self.config)
        log.info("Clipboard auto-restore: %s", "ON" if new_val else "OFF")

    def _toggle_press_enter_after_paste(self):
        """Flip the 'press Enter after auto-paste' setting — dictate + send
        for chat apps / REPLs."""
        new_val = not bool(self.config.get("press_enter_after_paste", False))
        self.config["press_enter_after_paste"] = new_val
        save_config(self.config)
        log.info("Press Enter after paste: %s", "ON" if new_val else "OFF")
        try:
            msg = ("  ⏎  Enter-after-paste ON  " if new_val
                   else "  Enter-after-paste OFF  ")
            self.overlay.show(msg, bg_color="#1e64c8" if new_val else "#334155",
                              duration=1500)
        except Exception:
            pass

    # ----- Meeting Mode -----
    def _is_meeting_active(self):
        """Thread-safe check — used by the tray menu predicates."""
        return self._active_meeting is not None

    def _toggle_meeting(self, summarize=False):
        """Start a meeting if none active, else stop the current one.
        Invoked from 'Start Meeting' (summarize=False), 'Start Meeting &
        Summarize' (summarize=True), and the Stop item.

        The transcription model — and whether the meeting is diarized
        or chunked — is determined by the user's Transcribe → Model
        selection (config['meeting_model']). `summarize` controls whether a
        gpt-5.5 summary is produced + popped up on stop.
        """
        with self._meeting_lock:
            already_active = self._active_meeting is not None
        if already_active:
            self._stop_meeting()
        else:
            self._start_meeting(summarize=summarize)

    def _self_speaker_name(self):
        """The display name to write for the LOCAL user's diarized cluster:
        config `speaker_self_name` when set, else the Windows account display
        name, else the USERNAME env var."""
        name = (self.config.get("speaker_self_name", "") or "").strip()
        if name:
            return name
        try:
            import ctypes
            sz = ctypes.c_ulong(0)
            ctypes.windll.secur32.GetUserNameExW(3, None, ctypes.byref(sz))
            buf = ctypes.create_unicode_buffer(max(2, sz.value + 1))
            if (ctypes.windll.secur32.GetUserNameExW(3, buf, ctypes.byref(sz))
                    and buf.value.strip()):
                return buf.value.strip()
        except Exception:
            pass
        return os.environ.get("USERNAME", "Me")

    def _llm_assign_speaker_names(self, utterances, candidates):
        """Speaker naming, phase 2: one narrow LOCAL gemma call matches the
        still-unnamed diarized labels to calendar CANDIDATE names from
        conversational evidence (see _SPEAKER_NAME_PASS_PROMPT). CODE enforces
        the contract (candidate membership, uniqueness, never overrides a name
        the deterministic layers set). Returns {label: name}; {} on anything."""
        try:
            unnamed = sorted({u.get("speaker") for u in utterances
                              if u.get("speaker") and not u.get("speaker_name")})
            taken = {u.get("speaker_name") for u in utterances
                     if u.get("speaker_name")}
            cands = [c for c in (candidates or []) if c
                     and c.casefold() not in {t.casefold() for t in taken}]
            if not unnamed or not cands:
                return {}
            evidence = _speaker_name_evidence(utterances, unnamed)
            if not evidence.strip():
                return {}
            model = (self.config.get("speaker_name_pass_model")
                     or "gemma4:31b-it-qat")
            cleaner = OpenAILLMCleaner(
                api_key="ollama", model=model,
                chat_url="http://localhost:11434/v1/chat/completions")
            content = ("CANDIDATES: " + ", ".join(cands)
                       + "\n\nSPEAKER LABELS TO IDENTIFY: " + ", ".join(unnamed)
                       + "\n\nTRANSCRIPT EXCERPTS:\n" + evidence)
            # The pass prompt follows the TRANSCRIPT's language (evidence
            # examples must match what the speakers actually said).
            ev_lang = lang_pack.detect_text_lang(evidence)
            prompt = (lang_pack.SPEAKER_NAME_PASS_PROMPT_EN if ev_lang == "en"
                      else _SPEAKER_NAME_PASS_PROMPT)
            num_ctx = max(8192, min(_SUMMARY_CTX_CAP,
                                    int(len(content)
                                        / lang_pack.chars_per_token(ev_lang))
                                    + 2048))
            t0 = time.time()
            resp = cleaner._ollama_summary_once(
                "http://localhost:11434/api/chat", prompt,
                content, num_ctx, False, 300, num_predict=300)
            votes = _parse_speaker_name_votes(resp or "", set(unnamed), cands,
                                              taken=taken)
            log.info("Speaker name pass (%s): %d/%d labels named in %.1fs",
                     model, len(votes), len(unnamed), time.time() - t0)
            return votes
        except Exception as e:
            log.warning("Speaker name pass failed (labels kept): %s", e)
            return {}

    def _fetch_meeting_attendees_async(self, session):
        """Speaker naming, phase 1a: ask the indexer helper (de-elevated - COM
        must reach the user's Medium-integrity Outlook) for the calendar
        appointment overlapping NOW, and stash its attendee display names on the
        session. Consumers: summary metadata (name spellings + owner evidence),
        the transcript header, the rename-speakers dialog suggestions.
        Fire-and-forget: any failure just leaves session.attendees empty."""
        import tempfile
        interp = find_python_interpreter()
        base_dir = os.path.dirname(os.path.abspath(__file__))
        indexer = os.path.join(base_dir, "emailsearch_indexer.py")
        if interp is None or not os.path.exists(indexer):
            return
        out_path = os.path.join(
            tempfile.gettempdir(), "lia_meeting_attendees_%d_%d.json"
            % (os.getpid(), int(time.time())))
        env = os.environ.copy()
        env["PYTHONIOENCODING"] = "utf-8"
        env["PYTHONUTF8"] = "1"
        spawn_helper([interp, "-X", "utf8", indexer, "--current-meeting", out_path],
                     env=env, creationflags=0x08000000)

        def waiter():
            deadline = time.time() + 90
            while time.time() < deadline:
                if os.path.exists(out_path):
                    try:
                        with open(out_path, encoding="utf-8") as f:
                            data = json.load(f)
                    except Exception as e:
                        log.warning("Meeting attendees: bad helper output: %s", e)
                        break
                    ms = [m for m in (data.get("meetings") or [])
                          if m.get("attendees")]
                    if ms:
                        m = ms[0]
                        session.attendees = list(m["attendees"])[:24]
                        session.event_subject = (m.get("subject") or "").strip()
                        log.info("Meeting attendees from calendar: %d (%s)",
                                 len(session.attendees),
                                 session.event_subject[:48])
                    else:
                        log.info("Meeting attendees: no overlapping calendar "
                                 "meeting with invitees")
                    break
                time.sleep(1.0)
            else:
                log.info("Meeting attendees: helper produced no output in 90s")
            try:
                os.remove(out_path)
            except Exception:
                pass

        threading.Thread(target=waiter, daemon=True,
                         name="meeting-attendees").start()

    def _start_meeting(self, summarize=False):
        """Start a long-form meeting capture using the selected meeting
        model. AssemblyAI Universal-2 → diarized recording. Anything
        else → chunked transcription with that model. When summarize=True a
        gpt-5.5 summary is produced and popped up (RTL) on stop."""
        # Summaries route to the configured summary model (OpenAI cloud, or a
        # LOCAL Ollama endpoint via summary_base_url). Degrade gracefully to a
        # plain transcript when neither is available — a keyless install still
        # gets a saved + shown transcript, just no LLM summary.
        if summarize and not self._summary_available():
            log.warning("Summarize meeting requested but no summary model available "
                        "(no OpenAI key / no local summary endpoint) — saving transcript only")
            summarize = False
        # Resolve the model first; if it can't be activated (missing API
        # key, load failure, etc.) fail loud BEFORE we open the recorder.
        model_key = self.config.get("meeting_model", "local_hebrew_turbo")
        # Keyless-friendly fallback: if the chosen meeting model needs an API
        # key that isn't set (fresh install, or a shipped config), transparently
        # fall back to the fully-local Hebrew model so the meeting still records
        # + transcribes instead of hard-blocking on a missing key.
        _required = {k: req for _lbl, k, req in self._MEETING_MODELS}.get(model_key, [])
        _missing = [k for k in _required if not (self.config.get(k, "") or "").strip()]
        if _missing:
            log.warning("Meeting model %s needs %s (missing) — falling back to "
                        "local_hebrew_turbo", model_key, ", ".join(_missing))
            model_key = "local_hebrew_turbo"
        transcriber, language, is_diarized = self._resolve_meeting_model(model_key)
        # Which model (if any) re-transcribes each AssemblyAI utterance for
        # better text. The menu choice is authoritative: 'AssemblyAI + GPT-4o'
        # → gpt-4o; 'AssemblyAI + Hebrew Turbo Local' → the local HE model;
        # 'AssemblyAI only' → none. Non-diarized models ignore this.
        diarize_enhance_model = {
            "assemblyai_universal_2": "openai_gpt4o",
            "assemblyai_local_hebrew": "local_hebrew_turbo",
            # Local diarize: pyannote gives ONLY speaker turns (no text), so the
            # per-turn transcription via ivrit.ai is mandatory, not an "enhance".
            "local_pyannote_hebrew": "local_hebrew_turbo",
            # English variant (2026-08): same pyannote turns, Parakeet per turn.
            "local_pyannote_parakeet": "local_parakeet_english",
        }.get(model_key)
        # Which engine finds the speaker turns. gemini_diarize returns text +
        # word timestamps directly (no separate enhance pass, so it is not in
        # diarize_enhance_model above); pyannote gives turns only; else AssemblyAI.
        if model_key == "gemini_diarize":
            diarize_backend = "gemini"
        elif model_key in ("local_pyannote_hebrew", "local_pyannote_parakeet"):
            diarize_backend = "local_pyannote"
        else:
            diarize_backend = "assemblyai"
        # Friendly transcription-engine name for the status card (computed AFTER
        # the keyless fallback so it reflects the model actually used).
        transcribe_label = self._meeting_transcribe_display(model_key)
        if transcriber is None:
            log.warning("Meeting blocked: model %r not available", model_key)
            # Map common cases to a clearer message + open the relevant
            # key dialog so the user can fix it on the spot.
            if model_key.startswith("openai_") and not self.config.get("openai_api_key", "").strip():
                self.overlay.show_error("Set OpenAI API key first")
                self._set_openai_api_key()
            elif model_key == "groq_turbo" and not self.config.get("groq_api_key", "").strip():
                self.overlay.show_error("Set Groq API key first")
                self._set_groq_api_key()
            elif model_key in ("assemblyai_universal_2", "assemblyai_diarize_only", "assemblyai_local_hebrew") and not self.config.get("assemblyai_api_key", "").strip():
                self.overlay.show_error("Set AssemblyAI API key first")
                self._set_assemblyai_api_key()
            else:
                self.overlay.show_error(f"Meeting model {model_key} unavailable")
            return

        with self._meeting_lock:
            if self._active_meeting is not None:
                return
            if self.is_recording:
                log.warning("Meeting blocked: a press-to-talk recording is active")
                self.overlay.show_error("Finish current recording first")
                return
            if (self._compose_active or self._compose_instr_active
                    or self._voice_ask_active):
                log.warning("Meeting blocked: a Compose/Voice-ask recording is active")
                self.overlay.show_error("Finish Compose first")
                return
            if not self.model_loaded:
                log.warning("Meeting blocked: model still loading")
                self.overlay.show_error("Model still loading")
                return
            try:
                session = MeetingSession(
                    self,
                    diarize_mode=is_diarized,
                    chunk_transcriber=(None if is_diarized else transcriber),
                    chunk_language=language,
                    summarize=summarize,
                    diarize_enhance_model=diarize_enhance_model,
                    diarize_backend=diarize_backend,
                    transcribe_label=transcribe_label,
                )
                session.start()
                self._active_meeting = session
                # Speaker naming, phase 1a: fetch the calendar attendees of the
                # meeting overlapping NOW (async, de-elevated COM helper).
                try:
                    self._fetch_meeting_attendees_async(session)
                except Exception as e:
                    log.warning("Meeting attendees fetch not started: %s", e)
            except Exception as e:
                log.error("Failed to start meeting: %s", e)
                self.overlay.show_error(f"Meeting start failed: {e}")
                return

        if self.tray_icon:
            self.tray_icon.icon = self._create_icon("meeting")
            label = ("Meeting recording (diarized)..." if is_diarized
                     else f"Meeting recording ({model_key})...")
            # Remember the specific title so the tray arbiter (_refresh_tray)
            # can restore it after transient states (dictation done, error
            # flash) instead of a generic label.
            self._meeting_tray_title = f"Lia - {label}"
            self.tray_icon.title = f"Lia - {label}"
            # Refresh the menu so the dynamic 'Start Meeting' label
            # flips to '⏹ Stop Meeting' and the Status line updates. On Windows
            # the menu text callables aren't re-evaluated until update_menu(), so
            # a meeting auto-started on a background thread otherwise leaves a
            # stale 'Start' label even though the meeting IS recording + tracked.
            try:
                self.tray_icon.update_menu()
            except Exception as e:
                log.debug("update_menu on meeting start failed: %s", e)
        suffix = " (+summary)" if summarize else ""
        overlay_msg = (f"  🎤  Diarized meeting recording started{suffix}  "
                       if is_diarized else
                       f"  🎙  Meeting recording started{suffix}  ")
        self.overlay.show(overlay_msg, bg_color="#581C87", duration=2500)
        # The persistent top-right Stop pill was removed per user
        # request — distracting during long meetings. The tray icon
        # turns purple while a meeting is active and exposes Stop
        # Meeting in its right-click menu (Transcribe -> Stop Meeting),
        # so the recording state is still visible without a floating
        # widget. show_recording_pill / hide_recording_pill helpers
        # remain in OverlayNotification for any future opt-in caller.
        # Auto-title: grab a meeting-name guess from the call window title now
        # (new Teams exposes it as the first '|'-segment). Logged so we can
        # confirm the real in-call title format on a live meeting and tune.
        try:
            session.title_guess = extract_meeting_name(
                prefer=getattr(self, "_meeting_detect_last_kind", None))
            log.info("Meeting title guess at start: %r", session.title_guess)
        except Exception as e:
            log.debug("Meeting title guess failed: %s", e)
        log.info("Meeting active (model=%s, diarized=%s, summarize=%s)",
                 model_key, is_diarized, summarize)

    def _prune_meeting_audio(self):
        """Delete kept meeting AUDIO past its retention — per FORMAT: WAV on
        meeting_wav_retention_days (~1 month), Opus on meeting_opus_retention_
        days (~2 years). Transcripts (.txt/.html) are never touched. 0 days for
        a format = keep it forever. Runs once at startup on a background thread.
        Best-effort."""
        def _days(key, default):
            try:
                return float(self.config.get(key, default) or 0)
            except (TypeError, ValueError):
                return default
        wav_days = _days("meeting_wav_retention_days", 30)
        opus_days = _days("meeting_opus_retention_days", 730)
        txt_days = _days("meeting_transcript_retention_days", 0)
        try:
            names = os.listdir(MEETINGS_DIR)
        except OSError:
            return
        now = time.time()
        removed = 0
        for name in names:
            low = name.lower()
            if low.endswith("_meeting_audio.wav"):
                days = wav_days
            elif (low.endswith("_meeting_audio.opus")
                  or low.endswith("_meeting_audio.opus.tmp")):
                days = opus_days
            elif (low.endswith("_meeting.txt")
                  or low.endswith("_meeting_diarized.txt")
                  or low.endswith("_meeting_live.txt")
                  or low.endswith("_meeting_partial.txt")
                  or low.endswith("_meeting_summary.html")):
                # Opt-in transcript retention (default 0 = keep forever). The
                # RAG index prunes deleted meetings on its next reindex.
                days = txt_days
            else:
                continue
            if days <= 0:
                continue                     # this format kept forever
            path = os.path.join(MEETINGS_DIR, name)
            try:
                if os.path.getmtime(path) < now - days * 86400:
                    os.remove(path)
                    removed += 1
            except OSError:
                pass
        if removed:
            log.info("Pruned %d expired meeting audio file(s) "
                     "(WAV>%.0fd, Opus>%.0fd)", removed, wav_days, opus_days)

    def _recap_available(self):
        """Menu-visibility: Recap & Continue shows only during a CHUNKED
        meeting (diarized has nothing to snapshot before its WAV closes)."""
        s = self._active_meeting
        try:
            return s is not None and not s.diarize_mode
        except Exception:
            return False

    def _live_transcript_available(self):
        """Menu-visibility for '📄 Live Transcript': ANY active meeting with a
        rolling live file — chunked, OR diarized (the parallel live-peek pass now
        keeps a live transcript in diarized meetings too)."""
        s = self._active_meeting
        try:
            return s is not None and getattr(s, "_live_path", None) is not None
        except Exception:
            return False

    def _open_live_transcript(self):
        """Tray → '📄 Live Transcript'. Opens the rolling LIVE transcript of
        the meeting in progress — read-only peeking, no LLM, no pipeline.
        The file is rewritten after every transcribed chunk (~45s)."""
        session = self._active_meeting
        if session is None:
            return
        p = getattr(session, "_live_path", None)
        if p and os.path.exists(p):
            try:
                os.startfile(p)
            except Exception as e:
                log.warning("Open live transcript failed: %s", e)
                self.overlay.show_error("Could not open live transcript")
        else:
            self.overlay.show_error("No transcript yet — first chunk lands in ~45s")

    def _recap_meeting(self):
        """Tray → '📋 Recap & Continue'. Mid-meeting checkpoint: transcript +
        summary of everything SO FAR pop up (summary opens in the WYSIWYG
        editor, like a meeting end) while the meeting keeps recording — the
        final Stop still yields the complete meeting. Use case: start
        speccing a solution from the first half while the second half runs."""
        session = self._active_meeting
        if session is None:
            return
        if session.diarize_mode:
            self.overlay.show_error("Recap works in chunked meetings only")
            return
        if session._recap_active:
            self.overlay.show_error("Recap already in progress")
            return
        session._recap_active = True
        self.overlay.show("  📋  Recap: transcribing + summarizing…  ",
                          bg_color="#581C87", duration=3000)

        def worker():
            try:
                res = session.recap()
                if not res:
                    self.overlay.show_error("Nothing to recap yet")
                    return
                txt_path, html_path, summary_md = res
                if html_path and os.path.exists(html_path):
                    # Same delivery as a meeting end: the WYSIWYG editor.
                    self._open_summary_editor(html_path)
                elif summary_md:
                    self.overlay.show_summary(
                        "Lia - סיכום ביניים", summary_md,
                        on_open_file=lambda p=txt_path: os.startfile(p))
                else:
                    os.startfile(txt_path)
                self._meeting_done_notify("Recap ready — meeting still recording")
            except Exception as e:
                log.exception("Recap failed: %s", e)
                self.overlay.show_error(f"Recap failed: {e}")
            finally:
                session._recap_active = False

        threading.Thread(target=worker, daemon=True).start()

    def _cancel_meeting(self):
        """Tray → 'Cancel Meeting (discard)'. Confirms first, then ends the
        meeting WITHOUT transcribing or saving a transcript. The recorded AUDIO
        is kept (so you can transcribe it later) unless keep_meeting_audio is
        off. For an accidental start or a meeting you don't need — stops spending
        tokens and writes no transcript/summary."""
        if not self._is_meeting_active():
            return
        keep_audio = bool(self.config.get("keep_meeting_audio", True))

        def _do_cancel():
            with self._meeting_lock:
                session = self._active_meeting
                if session is None:
                    return
                self._active_meeting = None
            # Reset the auto-detect state machine (same as a normal stop) so the
            # next call/meeting starts clean.
            with self._meeting_detect_lock:
                self._meeting_detect_state = 'idle'
                self._meeting_detect_user_kept_recording = False
                self._meeting_detect_consec_absent = 0
                self._meeting_detect_consec_present = 0
            self._stop_offer_count = 0
            self.overlay.hide_recording_pill()
            if self.tray_icon:
                self.tray_icon.icon = self._create_icon("processing")
                self.tray_icon.title = "Lia - Discarding meeting..."
                try:
                    self.tray_icon.update_menu()
                except Exception:
                    pass

            def _work():
                try:
                    session.cancel()
                except Exception as e:
                    log.error("Cancel meeting failed: %s", e)
                finally:
                    self._refresh_tray()
                    self._meeting_nudge(
                        "Meeting discarded — transcript dropped, audio kept"
                        if keep_audio else "Meeting discarded — nothing saved",
                        force=True)
            threading.Thread(target=_work, daemon=True).start()

        # Confirm before discarding — a stray click here would otherwise drop
        # a live recording's transcript. ✕ / timeout = keep recording.
        self.overlay.show_prompt(
            "Discard this meeting?",
            ("No transcript or summary will be saved — but the audio is kept "
             "so you can transcribe it later."
             if keep_audio else
             "The recording will be deleted — nothing transcribed or saved."),
            "🗑  Discard",
            on_action=_do_cancel,
            duration_ms=20000,
        )

    def _stop_meeting(self, summarize=None):
        """Stop the in-progress meeting, save the transcript file, and surface
        the result. Regular mode opens the transcript; "& Summarize" mode pops
        up the gpt-5.5 summary (the file is saved silently in the background).
        Diarized meetings finalise ASYNC in _run_diarize_job.

        `summarize` (2026-08-29): an explicit end-time override from the tray
        ("End Meeting & Summarize" / "End Meeting (no summary)"). None keeps
        the session's start-time choice (auto-detect / watchdog / pill stops)."""
        with self._meeting_lock:
            session = self._active_meeting
            if session is None:
                return
            self._active_meeting = None
        if summarize is not None:
            session.summarize = bool(summarize)

        # Reset the auto-detect state machine so the next call/meeting starts
        # clean — covers a manual stop of an 'adopted' meeting (otherwise the
        # state could linger as 'running').
        with self._meeting_detect_lock:
            self._meeting_detect_state = 'idle'
            self._meeting_detect_user_kept_recording = False
            self._meeting_detect_consec_absent = 0
            self._meeting_detect_consec_present = 0
        self._stop_offer_count = 0   # re-enable stop-offers for the next meeting

        # Tear down the persistent Stop pill regardless of how stop was
        # triggered (Stop button click, tray menu, auto-detect prompt).
        self.overlay.hide_recording_pill()

        if self.tray_icon:
            self.tray_icon.icon = self._create_icon("processing")
            self.tray_icon.title = "Lia - Finalising meeting..."
            # Flip the menu label back to 'Start Meeting' now that
            # _active_meeting is None (else it stays a stale '⏹ Stop Meeting').
            try:
                self.tray_icon.update_menu()
            except Exception as e:
                log.debug("update_menu on meeting stop failed: %s", e)

        # Resolve the meeting title (auto from the call window, else the quick
        # stop-prompt) BEFORE the writer runs so the file is named right — for
        # BOTH diarized AND chunked meetings (chunked used to be named by
        # timestamp only, so titles "disappeared" from filenames). Always sets
        # session._title_event so the writer (which waits on it) never hangs.
        self._resolve_meeting_title(session)

        # Heavy lifting (last chunk transcription + LLM summary) runs in a
        # thread so the tray stays responsive. The persistent status card is
        # the user-facing progress UI — diarized meetings drive it from inside
        # _run_diarize_job (async); chunked meetings drive it here.
        folder_cb = lambda: os.startfile(MEETINGS_DIR)

        def finalise():
            path = None
            if not session.diarize_mode:
                cstages = [("finalize", "Finalizing transcript")]
                if session.summarize:
                    cstages.append(("summarize", "Summarizing"))
                _sub = (f"Transcribing with {session.transcribe_label}"
                        if getattr(session, "transcribe_label", "") else "")
                session._card_gen = self.overlay.meeting_status_start(
                    cstages, title="Processing meeting", subtitle=_sub)
                self.overlay.meeting_status_step("finalize", gen=session._card_gen)
            try:
                path = session.stop(save=True)
            except Exception as e:
                log.exception("Meeting finalisation failed: %s", e)
                if not session.diarize_mode:
                    self.overlay.meeting_status_error(
                        "finalize", "Meeting save failed", on_folder=folder_cb,
                        gen=session._card_gen)
                self._refresh_tray()
                # `path` is unbound here — falling through used to crash this
                # worker with UnboundLocalError right after queuing the error
                # card. The card stays up; we're done.
                return
            finally:
                self._refresh_tray()
            # Diarized meetings finish ASYNC inside _run_diarize_job
            # (AssemblyAI takes minutes); it owns the card + completion there.
            if session.diarize_mode:
                return
            if path and os.path.exists(path):
                # Actionable completion card — NO file auto-opens. "Open" =
                # the RTL summary popup (summarize mode) or the transcript .txt.
                if session.summarize and session.last_summary:
                    def _open(p=path, s=session.last_summary,
                              h=session.summary_html_path):
                        if h and os.path.exists(h):
                            self._open_summary_editor(h)   # the WYSIWYG editor
                        else:
                            self.overlay.show_summary(
                                "Meeting summary", s,
                                on_open_file=lambda: os.startfile(p))
                    self.overlay.meeting_status_finish(
                        title="Summary ready", on_open=_open,
                        on_folder=folder_cb,
                        gen=getattr(session, "_card_gen", None))
                    # Auto-open the summary in the editor (off-thread).
                    if session.summary_html_path and os.path.exists(session.summary_html_path):
                        threading.Thread(
                            target=lambda h=session.summary_html_path:
                                self._open_summary_editor(h),
                            daemon=True).start()
                    self._meeting_done_notify("Summary ready")
                else:
                    self.overlay.meeting_status_finish(
                        title="Transcript ready",
                        on_open=lambda p=path: os.startfile(p),
                        on_folder=folder_cb,
                        gen=getattr(session, "_card_gen", None))
                    self._meeting_done_notify("Transcript ready")
                self._play_done_beep()
            else:
                # Nothing usable was produced — clear the card.
                self.overlay.meeting_status_hide()

        # Track the in-flight finalize so a quit/restart can dump a chunked
        # transcript that's still only in memory. Cleared once finalise()
        # returns — for chunked that's after the file is written; for diarized
        # the WAV is already on disk (recoverable), and the long part runs in
        # _run_diarize_job which finalise() doesn't block on.
        self._finalizing_meeting = session

        def _finalise_wrapper():
            try:
                finalise()
            finally:
                self._finalizing_meeting = None

        threading.Thread(target=_finalise_wrapper, daemon=True).start()

    def _meeting_done_notify(self, title):
        """Fire a native tray balloon when a meeting finishes processing — a
        nudge in case the user is in another window and missed the card."""
        try:
            if self.tray_icon:
                self.tray_icon.notify(f"{title} — open it from the card", "Lia")
        except Exception:
            pass

    def _open_meetings_folder(self):
        """Tray → open the meetings folder in Explorer."""
        try:
            os.makedirs(MEETINGS_DIR, exist_ok=True)
            os.startfile(MEETINGS_DIR)
        except Exception as e:
            log.warning("Could not open meetings folder: %s", e)

    def _edit_meeting_summary(self):
        """Tray → pick a meeting-summary *.html and open it in the WYSIWYG editor.

        The picker runs on a throwaway Tk root (off the pystray thread); the
        editor itself is a pywebview subprocess (compose_editor.py) so Hebrew
        bidi renders perfectly. Any failure falls back to opening the file in
        the browser."""
        def worker():
            import tkinter as tk
            from tkinter import filedialog
            try:
                os.makedirs(MEETINGS_DIR, exist_ok=True)
            except Exception:
                pass
            path = None
            try:
                root = tk.Tk()
                _apply_dpi_scaling_to_tk(root)
                root.withdraw()
                root.attributes('-topmost', True)
                try:
                    path = filedialog.askopenfilename(
                        title="בחר סיכום פגישה לעריכה",
                        initialdir=MEETINGS_DIR,
                        filetypes=[("Meeting summaries", "*_meeting_summary.html"),
                                   ("HTML files", "*.html *.htm"),
                                   ("All files", "*.*")],
                        parent=root,
                    )
                except Exception:
                    path = None
                try:
                    root.destroy()
                except Exception:
                    pass
            except Exception as e:
                log.warning("Edit-summary picker failed: %s", e)
                return
            if not path:
                return
            self._open_summary_editor(path)

        threading.Thread(target=worker, daemon=True).start()

    def _rename_speakers_in_old_meeting(self):
        """Settings > Meetings: pick an old diarized transcript and open the
        speaker-rename dialog. Text rename works on any saved transcript; voice
        preview works when the Opus archive is still on disk; voiceprint
        learning is unavailable (no in-memory embeddings - the guard in
        _rename_speakers_dialog handles this gracefully)."""
        def worker():
            import tkinter as tk
            from tkinter import filedialog
            try:
                os.makedirs(MEETINGS_DIR, exist_ok=True)
            except Exception:
                pass
            path = None
            try:
                root = tk.Tk()
                _apply_dpi_scaling_to_tk(root)
                root.withdraw()
                root.attributes('-topmost', True)
                try:
                    path = filedialog.askopenfilename(
                        title="Select a diarized meeting to rename speakers",
                        initialdir=MEETINGS_DIR,
                        filetypes=[
                            ("Diarized transcripts", "*_meeting_diarized.txt"),
                            ("Text files", "*.txt"),
                            ("All files", "*.*"),
                        ],
                        parent=root,
                    )
                except Exception:
                    path = None
                try:
                    root.destroy()
                except Exception:
                    pass
            except Exception as e:
                log.warning("Rename-speakers picker failed: %s", e)
                return
            if not path:
                return
            self._rename_speakers_dialog(path)

        threading.Thread(target=worker, daemon=True).start()

    def _open_email_search(self):
        """Open the local Outlook email-search window (long-lived, non-blocking)
        and kick a background index refresh. This process NEVER touches Outlook
        COM — the window reads the local index; the indexer subprocess owns COM,
        so a wedge can't freeze the tray/UI. No-op on a frozen build."""
        import subprocess
        import tempfile
        base_dir = os.path.dirname(os.path.abspath(__file__))
        interp = find_python_interpreter()
        script = os.path.join(base_dir, "email_search.py")
        indexer = os.path.join(base_dir, "emailsearch_indexer.py")
        if interp is None or not os.path.exists(script):
            log.warning("Email search unavailable (no interpreter / script).")
            return

        ollama_url = (self.config.get("summary_base_url")
                      or "http://localhost:11434/v1/chat/completions")
        answer_model = (self.config.get("email_answer_model")
                        or self.config.get("summary_model") or "gemma4:31b-it-qat")
        if answer_model != "gemma4:31b-it-qat":
            answer_model = "gemma4:31b-it-qat"   # v1 answers are LOCAL only
        payload = {
            "mode": "email_search",
            "title": "Email search - Lia",
            "base_url": ollama_url,
            "answer_model": answer_model,
            "models": [["Gemma 4 31B QAT", "gemma4:31b-it-qat"]],
        }
        env = os.environ.copy()
        env["PYTHONIOENCODING"] = "utf-8"
        env["PYTHONUTF8"] = "1"
        flags = 0x08000000  # CREATE_NO_WINDOW

        try:
            self._kick_email_indexer(interp, indexer, ollama_url, env, flags)
        except Exception as e:
            log.warning("Email indexer kick failed: %s", e)

        try:
            fd, payload_path = tempfile.mkstemp(suffix=".json", prefix="wt_emailsearch_")
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(payload, f, ensure_ascii=False)
        except Exception as e:
            log.warning("Email search payload write failed: %s", e)
            return
        try:
            # De-elevate when we're elevated so the window's COM can reach the
            # user's (Medium-integrity) Outlook for "Open in Outlook".
            spawn_helper([interp, "-X", "utf8", script, payload_path],
                         env=env, creationflags=flags)
            log.info("Email search window opened.")
        except Exception as e:
            log.warning("Email search spawn failed: %s", e)
            return

        def _cleanup():
            time.sleep(20)
            try:
                os.remove(payload_path)
            except Exception:
                pass
        threading.Thread(target=_cleanup, daemon=True).start()

    def _open_chat_window(self):
        """Open the free-form chat window (local Ollama models by default; cloud
        gpt-5.5 offered when an OpenAI key is set). Long-lived, non-blocking; a
        fresh subprocess so it can't freeze the tray. No-op on a frozen build."""
        import tempfile
        base_dir = os.path.dirname(os.path.abspath(__file__))
        interp = find_python_interpreter()
        script = os.path.join(base_dir, "chat_window.py")
        if interp is None or not os.path.exists(script):
            log.warning("Chat unavailable (no interpreter / script).")
            return

        ollama_url = (self.config.get("summary_base_url")
                      or "http://localhost:11434/v1/chat/completions")
        # Local Ollama model. Gemma 4 31B QAT is 18.9 GB → sits fully on the
        # 24 GB 3090, and is the only local model the app ships with.
        models = [["Gemma 4 31B QAT", "gemma4:31b-it-qat"]]
        cloud_models = []
        openai_key = (self.config.get("openai_api_key", "") or "").strip()
        # FAIL CLOSED (audit follow-up): the payload file must never hold a
        # plaintext key. If DPAPI cannot protect it, ship the chat local-only.
        protected_key = secret_store.protect(openai_key)
        if openai_key and not secret_store.is_protected(protected_key):
            log.warning("Chat: DPAPI protection unavailable - cloud model "
                        "disabled (a key is never written to disk in plaintext)")
            openai_key, protected_key = "", ""
        if openai_key:
            models.append(["ChatGPT 5.5 (ענן)", "gpt-5.5"])
            cloud_models.append("gpt-5.5")
        default_model = (self.config.get("chat_model")
                         or self.config.get("summary_model") or "gemma4:31b-it-qat")
        if default_model not in [m[1] for m in models]:
            default_model = models[0][1]
        payload = {
            "mode": "chat",
            "title": "Chat - Lia",
            "base_url": ollama_url,
            "models": models,
            "cloud_models": cloud_models,
            "default_model": default_model,
            # DPAPI-protected: the child unprotects (same user = decryptable).
            "openai_key": protected_key,
            # A custom prompt wins; else an English-primary user gets the EN
            # default ("" keeps the child's Hebrew DEFAULT_SYSTEM).
            "system_prompt": ((self.config.get("chat_system_prompt", "") or "")
                              or (lang_pack.CHAT_SYSTEM_EN
                                  if lang_pack.primary_language(self.config) == "en"
                                  else "")),
        }
        env = os.environ.copy()
        env["PYTHONIOENCODING"] = "utf-8"
        env["PYTHONUTF8"] = "1"
        flags = 0x08000000  # CREATE_NO_WINDOW

        try:
            fd, payload_path = tempfile.mkstemp(suffix=".json", prefix="wt_chat_")
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(payload, f, ensure_ascii=False)
        except Exception as e:
            log.warning("Chat payload write failed: %s", e)
            return
        try:
            # De-elevate when elevated (spawn_helper falls back to Popen); the chat
            # only needs localhost Ollama / HTTPS, but keep the spawn consistent.
            spawn_helper([interp, "-X", "utf8", script, payload_path],
                         env=env, creationflags=flags)
            log.info("Chat window opened.")
        except Exception as e:
            log.warning("Chat spawn failed: %s", e)
            return

        def _cleanup():
            time.sleep(20)
            try:
                os.remove(payload_path)
            except Exception:
                pass
        threading.Thread(target=_cleanup, daemon=True).start()

