    def _kick_meetings_indexer_bg(self):
        """Fire-and-forget incremental reindex after a meeting is saved, so the
        ask-your-meetings index stays fresh. Daemon thread; heartbeat-guarded
        inside _kick_meetings_indexer; no-op on a frozen build or when disabled."""
        if not self.config.get("meetings_autoindex", True):
            return

        def _run():
            try:
                interp = find_python_interpreter()
                if interp is None:
                    return
                ollama = (self.config.get("summary_base_url") or self._OLLAMA_CHAT_URL)
                env = os.environ.copy()
                env["PYTHONIOENCODING"] = "utf-8"
                env["PYTHONUTF8"] = "1"
                self._kick_meetings_indexer(interp, ollama, env, 0x08000000)
            except Exception as e:
                log.debug("Meetings auto-index kick failed: %s", e)
        threading.Thread(target=_run, daemon=True).start()

    def _meetings_reindex_watchdog(self):
        """Periodic incremental reindex of the ask-your-meetings index. Save- and
        open-triggers already cover NEW meetings; this catches summary EDITS (an mtime
        change with no save/open event) and lets the indexer's prune pass drop deleted
        meetings on a schedule. Config `meetings_reindex_interval_min` (0 disables);
        reuses the autoindex-gated bg kicker (heartbeat-guarded downstream). Skipped
        while recording / in a meeting / composing to avoid GPU + embedding contention."""
        MIN_TICK_SEC = 60
        while True:
            try:
                mins = int(self.config.get("meetings_reindex_interval_min", 360) or 0)
            except (ValueError, TypeError):
                mins = 360
            if mins <= 0:
                time.sleep(30 * 60)          # disabled — re-check every 30 min
                continue
            time.sleep(max(MIN_TICK_SEC, mins * 60))
            try:
                if (self.is_recording or self._is_meeting_active()
                        or self._compose_active or self._compose_instr_active
                        or self._voice_ask_active):
                    continue
                self._kick_meetings_indexer_bg()   # self-gates on meetings_autoindex
            except Exception as e:
                log.debug("Meetings reindex watchdog tick failed: %s", e)

    def _kick_email_indexer(self, interp, indexer, ollama_url, env, flags):
        """Spawn the indexer subprocess (incremental; --full if no index yet),
        unless one ran in the last ~20s (heartbeat guard against double-runs)."""
        import subprocess
        try:
            import email_index as _ei
        except Exception:
            return
        if not os.path.exists(indexer):
            return
        hb = os.path.join(_ei.EMAIL_DIR, "index_heartbeat.txt")
        try:
            if os.path.exists(hb) and (time.time() - os.path.getmtime(hb)) < 20:
                return  # an indexer is (probably) already running
        except OSError:
            pass
        args = [interp, "-X", "utf8", indexer, "--base-url", ollama_url]
        if not os.path.exists(_ei.MESSAGES_DB):
            args.append("--full")
        # De-elevate when elevated so the indexer's Outlook COM works.
        spawn_helper(args, env=env, creationflags=flags)
        log.info("Email indexer kicked (%s).",
                 "full" if "--full" in args else "incremental")

    # ---- Ask your meetings (local RAG over the meeting archive) -------------
    def _meetings_providers(self):
        """Build the answer-model dropdown for the ask window from the API keys
        that are configured. Retrieval is ALWAYS local; only the ANSWER model
        varies. Returns (providers_list, default_index). Each provider is
        {label, base_url, model, key, provider}."""
        ollama = (self.config.get("summary_base_url") or self._OLLAMA_CHAT_URL)
        provs = [{
            "label": "Gemma 4 (מקומי · חינם)", "provider": "local",
            "base_url": ollama, "key": "ollama",
            "model": self.config.get("meetings_answer_model_local", "gemma4:31b-it-qat")}]
        gm = (self.config.get("gemini_api_key", "") or "").strip()
        if gm:
            provs.append({
                "label": "Gemini Flash (ענן · חינם)", "provider": "gemini",
                "base_url": GEMINI_CHAT_URL, "key": gm,
                "model": self.config.get("meetings_answer_model_gemini", "gemini-3.7-flash")})
        gq = (self.config.get("groq_api_key", "") or "").strip()
        if gq:
            provs.append({
                "label": "Groq Llama (ענן · חינם)", "provider": "groq",
                "base_url": GroqLLMCleaner.CHAT_URL, "key": gq,
                "model": self.config.get("meetings_answer_model_groq", "llama-3.3-70b-versatile")})
        oa = (self.config.get("openai_api_key", "") or "").strip()
        if oa:
            om = self.config.get("meetings_answer_model_openai", "gpt-5.6-luna")
            provs.append({
                "label": "GPT-5.6 %s (ענן · בתשלום)" % om.rsplit("-", 1)[-1].title(),
                "provider": "openai", "base_url": OpenAILLMCleaner.CHAT_URL,
                "key": oa, "model": om})
        pref = self.config.get("meetings_answer_provider", "local")
        default = next((i for i, p in enumerate(provs) if p["provider"] == pref), 0)
        return provs, default

    def _kick_meetings_indexer(self, interp, ollama_url, env, flags):
        """Spawn the meetings indexer (incremental; --full if no index yet),
        unless one ran in the last ~20s. No COM, no de-elevation needed."""
        try:
            import meetings_index as _mi
        except Exception:
            return
        script = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                              "meetings_index.py")
        if not os.path.exists(script):
            return
        try:
            if (os.path.exists(_mi.HEARTBEAT_FILE)
                    and (time.time() - os.path.getmtime(_mi.HEARTBEAT_FILE)) < 20):
                return
        except OSError:
            pass
        args = [interp, "-X", "utf8", script, "--base-url", ollama_url]
        if not os.path.exists(_mi.MESSAGES_DB):
            args.append("--full")
        spawn_helper(args, env=env, creationflags=flags)
        log.info("Meetings indexer kicked (%s).",
                 "full" if "--full" in args else "incremental")

    def _open_meetings_ask(self):
        """Open the 'Ask your meetings' window. Kicks the local indexer first,
        then spawns the pywebview panel as its own subprocess (non-blocking).
        No-op on a frozen build."""
        import tempfile
        base_dir = os.path.dirname(os.path.abspath(__file__))
        interp = find_python_interpreter()
        script = os.path.join(base_dir, "meetings_search.py")
        if interp is None or not os.path.exists(script):
            log.warning("Ask-your-meetings unavailable (no interpreter / script).")
            return
        ollama_url = (self.config.get("summary_base_url") or self._OLLAMA_CHAT_URL)
        env = os.environ.copy()
        env["PYTHONIOENCODING"] = "utf-8"
        env["PYTHONUTF8"] = "1"
        flags = 0x08000000  # CREATE_NO_WINDOW
        # Refresh the index (new/changed meetings) before the window reads it.
        try:
            self._kick_meetings_indexer(interp, ollama_url, env, flags)
        except Exception as e:
            log.warning("Meetings indexer kick failed: %s", e)
        providers, default = self._meetings_providers()
        # DPAPI-protect the provider keys: the payload file must never hold a
        # plaintext API key on disk (the child unprotects; same user). FAIL
        # CLOSED: a provider whose key cannot be protected is DROPPED (the
        # local provider always remains).
        safe_providers = []
        for p in providers:
            key = p.get("key") or ""
            if key and key != "ollama":
                blob = secret_store.protect(key)
                if not secret_store.is_protected(blob):
                    log.warning("Ask-your-meetings: DPAPI protection "
                                "unavailable - dropping cloud provider %s",
                                p.get("provider"))
                    continue
                p = dict(p, key=blob)
            safe_providers.append(p)
        providers = safe_providers
        payload = {
            "title": "Ask your meetings - Lia",
            "embed_base_url": ollama_url,          # retrieval (bge-m3) is LOCAL
            "providers": providers,                # answer-model dropdown
            "default_provider": default,
            "top_k": int(self.config.get("meetings_top_k", 20) or 20),
            "intent_routing": bool(self.config.get("meetings_intent_routing", True)),
        }
        try:
            fd, payload_path = tempfile.mkstemp(suffix=".json", prefix="wt_meetask_")
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(payload, f, ensure_ascii=False)
        except Exception as e:
            log.warning("Meetings-ask payload write failed: %s", e)
            return
        try:
            spawn_helper([interp, "-X", "utf8", script, payload_path],
                         env=env, creationflags=flags)
            log.info("Ask-your-meetings window opened.")
        except Exception as e:
            log.warning("Meetings-ask spawn failed: %s", e)
            return

        def _cleanup():
            time.sleep(20)
            try:
                os.remove(payload_path)
            except Exception:
                pass
        threading.Thread(target=_cleanup, daemon=True).start()

    def _open_summary_editor(self, html_path):
        """Spawn compose_editor.py in summary_html mode for `html_path`.

        Blocks the calling thread for the window's lifetime (pywebview's loop),
        so callers must invoke this from a worker thread. On ANY failure —
        frozen build, missing editor, spawn error, non-zero exit — falls back
        to opening the HTML in the default browser (read-only but correct RTL)."""
        def fallback(reason=None):
            if reason:
                log.warning("Summary editor fallback: %s", reason)
            try:
                os.startfile(html_path)
            except Exception as e:
                log.warning("Could not open summary HTML: %s", e)

        interp = find_python_interpreter()
        if interp is None:
            fallback("frozen build — no interpreter; opening in browser")
            return
        script = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                              "compose_editor.py")
        if not os.path.exists(script):
            fallback("compose_editor.py not found")
            return

        import subprocess
        import tempfile
        payload = {"mode": "summary_html", "path": html_path,
                   "title": "Edit meeting summary"}
        payload_path = None
        try:
            fd, payload_path = tempfile.mkstemp(suffix=".json", prefix="wt_summary_")
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(payload, f, ensure_ascii=False)
        except Exception as e:
            fallback("could not write payload: %s" % e)
            return

        env = os.environ.copy()
        env["PYTHONIOENCODING"] = "utf-8"  # Hebrew payload/result + Hebrew %TEMP%
        env["PYTHONUTF8"] = "1"            # match -X utf8 (Hebrew argv path)
        result = None
        try:
            result = subprocess.run(
                [interp, "-X", "utf8", script, payload_path],
                capture_output=True, env=env,
                creationflags=0x08000000,  # CREATE_NO_WINDOW
            )
        except Exception as e:
            fallback("spawn failed: %s" % e)
            return
        finally:
            try:
                if payload_path:
                    os.remove(payload_path)
            except Exception:
                pass

        if result.returncode != 0:
            fallback("editor exited %d: %s" % (
                result.returncode,
                result.stderr.decode("utf-8", errors="replace")[:200]))
            return

        # Parse the (informational) COMPOSE_RESULT line; the child already saved.
        try:
            for line in result.stdout.decode("utf-8", errors="replace").splitlines():
                if line.startswith("COMPOSE_RESULT "):
                    data = json.loads(line[len("COMPOSE_RESULT "):])
                    if data.get("exported"):
                        log.info("Meeting summary edited & saved: %s", html_path)
                    break
        except Exception:
            pass

    def _meeting_nudge(self, msg, color="#581C87", force=False):
        """A notice while a meeting records: a native tray balloon plus a brief
        overlay toast. `force=True` bypasses silent_mode for the overlay toast —
        the AUTO-STOP notice ("your meeting was just stopped") is important
        enough that an Invisible-Mode user must see it (the plain show() is
        silenced, leaving only the balloon, itself suppressed by Focus Assist)."""
        try:
            if self.tray_icon:
                self.tray_icon.notify(msg, "Lia")
        except Exception:
            pass
        if force and getattr(self.overlay, "silent", False):
            was = self.overlay.silent
            try:
                self.overlay.silent = False
                self.overlay.show("  ⏺  " + msg + "  ", bg_color=color, duration=4500)
            except Exception:
                pass
            def _restore():
                time.sleep(5.0)
                self.overlay.silent = bool(self.config.get("silent_mode", was))
            threading.Thread(target=_restore, daemon=True).start()
        else:
            try:
                self.overlay.show("  ⏺  " + msg + "  ", bg_color=color, duration=4500)
            except Exception:
                pass

    def _meeting_watchdog(self):
        """Forgotten-meeting safeguards. Runs always; acts only while a meeting
        is recording. Every 30s:

          - SILENCE stop-OFFER: after meeting_silence_prompt_min (default 5) of
            continuous silence, show the 'Stop the recording?' card + balloon.
            The early, polite layer — and the only net that's driven by the
            RECORDING itself, so it works for manual/undetected meetings too.
          - SILENCE auto-stop: stop after meeting_silence_stop_min of CONTINUOUS
            silence (no chunk with voice). The catch-all for "the call ended /
            I left and forgot" — a ~1h silence is unambiguous (nothing like the
            rejected press-to-talk silence-stop, which cut on sub-second pauses).
          - HARD CAP: auto-stop + finalize at meeting_max_duration_min regardless
            of audio — the backstop for a runaway that keeps low chatter so the
            silence net never trips (e.g. the ~10h 2026-06-04 orphan).
          - REMINDERS: a "still recording" nudge after meeting_reminder_first_min,
            then every meeting_reminder_every_min, so you stop it yourself.

        The 'call ended → Stop?' prompt (60s of sustained call ABSENCE) lives in
        the auto-detect loop; both prompts share _show_meeting_stop_prompt.
        """
        POLL = 30.0
        while not self._meeting_detect_stop_event.wait(POLL):
            try:
                with self._meeting_lock:
                    session = self._active_meeting
                if session is None or not getattr(session, "_active", False):
                    continue

                # Auto-title: if we didn't get a name at start (e.g. lobby →
                # call title change), keep trying while the meeting runs.
                if not getattr(session, "title_guess", None):
                    try:
                        g = extract_meeting_name(
                            prefer=getattr(self, "_meeting_detect_last_kind", None))
                        if g:
                            session.title_guess = g
                    except Exception:
                        pass

                # --- Silence auto-stop ---
                sil_min = int(self.config.get("meeting_silence_stop_min", 60) or 0)
                if sil_min > 0 and session.seconds_since_voice() >= sil_min * 60:
                    log.info("Meeting auto-stop: %d min of continuous silence", sil_min)
                    self._meeting_nudge(
                        f"Meeting auto-stopped — {sil_min} min of silence",
                        color="#6b0f1a", force=True)
                    self._stop_meeting()
                    continue

                # --- Silence stop-OFFER (the early, polite layer) ---
                # Detects "the meeting is over" from the AUDIO itself, so it
                # works even when call-end detection misses (new-Teams audio-
                # session flakiness) and for manual meetings that were never
                # adopted into the detector. Re-offers every interval while
                # the silence continues; an explicit ✕ ('keep recording')
                # suppresses it for the rest of the meeting.
                prompt_min = int(self.config.get("meeting_silence_prompt_min", 5) or 0)
                if prompt_min > 0 and not self._meeting_detect_user_kept_recording:
                    sil = session.seconds_since_voice()
                    last_offer = getattr(session, "_silence_prompt_ts", 0.0)
                    if (sil >= prompt_min * 60
                            and time.time() - last_offer >= prompt_min * 60):
                        with self._meeting_detect_lock:
                            st = self._meeting_detect_state
                        if st in ('idle', 'running'):
                            session._silence_prompt_ts = time.time()
                            mins = int(sil // 60)
                            log.info("Meeting silence prompt: ~%d min without "
                                     "voice — offering to stop", mins)
                            self._show_meeting_stop_prompt(
                                reason="silence", silent_min=mins)

                # --- Hard duration cap (backstop the silence net misses: a
                # forgotten call that keeps low chatter never goes "silent") ---
                cap_min = int(self.config.get("meeting_max_duration_min", 120) or 0)
                if cap_min > 0 and session.elapsed_seconds() >= cap_min * 60:
                    log.info("Meeting auto-stop: hit %d min hard cap", cap_min)
                    self._meeting_nudge(
                        f"Meeting auto-stopped — {cap_min} min limit reached",
                        color="#6b0f1a", force=True)
                    self._stop_meeting()
                    continue

                # --- Periodic 'still recording' reminders ---
                first = int(self.config.get("meeting_reminder_first_min", 30) or 0)
                every = int(self.config.get("meeting_reminder_every_min", 30) or 0)
                if first > 0:
                    elapsed_min = session.elapsed_seconds() / 60.0
                    if elapsed_min >= first:
                        due = 1 + (int((elapsed_min - first) // every) if every > 0 else 0)
                    else:
                        due = 0
                    if due > getattr(session, "_reminders_shown", 0):
                        session._reminders_shown = due
                        em = int(session.elapsed_seconds() // 60)
                        self._meeting_nudge(
                            f"Meeting still recording — {em} min. Stop it from the "
                            f"tray (Transcribe → Stop Meeting) if you're done.")
            except Exception as e:
                log.warning("Meeting watchdog iteration failed: %s", e)

    # ----- Meeting auto-detect (Zoom / Teams / Meet) -----
    def _toggle_auto_detect_meetings(self):
        """Flip the 'Auto-detect Zoom/Teams/Meet' setting. When ON, a
        background thread polls top-level windows every ~5s and shows a
        clickable overlay when an active call window appears."""
        new_val = not bool(self.config.get("auto_detect_meetings", False))
        self.config["auto_detect_meetings"] = new_val
        save_config(self.config)
        log.info("Auto-detect meetings: %s", "ON" if new_val else "OFF")
        if new_val:
            self.overlay.show(
                "  🎙  Auto-detect meetings ON  ",
                bg_color="#1e64c8", duration=1500)
        else:
            self.overlay.show(
                "  Auto-detect meetings OFF  ",
                bg_color="#334155", duration=1500)
        # Reset state so a previous dismissed kind doesn't carry over.
        with self._meeting_detect_lock:
            self._meeting_detect_state = 'idle'
            self._meeting_detect_consec_present = 0
            self._meeting_detect_consec_absent = 0
            self._meeting_detect_dismissed_kinds = set()
            self._meeting_detect_user_kept_recording = False

    def _meeting_detector_loop(self):
        """Background thread. Polls top-level windows + audio sessions
        every POLL_INTERVAL seconds, and drives the auto-detect state
        machine.

        Two separate stability thresholds:
          - START_CONFIRM_POLLS (10s) — stable detection before showing
            the Start prompt. Short, because a stable signal is enough
            to ask the user.
          - STOP_CONFIRM_POLLS (60s) — stable ABSENCE before showing the
            Stop prompt. Long, because Teams audio-session-Active goes
            Inactive during normal silences in a call (every time
            nobody is speaking). Treating 10s of Inactive as "call
            ended" would fire the Stop prompt every minute of a real
            meeting.

        `auto_detect_meetings` is checked each iteration so the user
        can toggle without restarting the app.
        """
        POLL_INTERVAL = 5.0
        START_CONFIRM_POLLS = 2   # 10s of stable signal before Start prompt
        STOP_CONFIRM_POLLS = 12   # 60s of stable absence before Stop prompt
        log.info("Meeting auto-detect thread started")
        while not self._meeting_detect_stop_event.is_set():
            try:
                if not self.config.get("auto_detect_meetings", False):
                    # Toggle is off — sleep and recheck. Don't bother
                    # enumerating windows or audio sessions.
                    if self._meeting_detect_stop_event.wait(POLL_INTERVAL):
                        break
                    continue

                hit = detect_active_meeting()
                with self._meeting_detect_lock:
                    state = self._meeting_detect_state
                meeting_active = self._is_meeting_active()

                if hit is not None:
                    kind, title, _proc = hit
                    # Remembered so auto-title prefers the DETECTED app's
                    # window name (a background Teams chat window otherwise
                    # mis-titled an active Zoom meeting).
                    self._meeting_detect_last_kind = kind
                    self._meeting_detect_consec_absent = 0
                    self._meeting_detect_consec_present += 1
                    # A meeting is ALREADY recording (e.g. started manually from
                    # the tray) and a call is now detected — 'adopt' it so the
                    # call-ended Stop prompt covers manual meetings too, not just
                    # auto-started ones. (Only when a call is actually present,
                    # so a mic-only manual meeting never gets a spurious prompt.)
                    if state == 'idle' and meeting_active:
                        with self._meeting_detect_lock:
                            if self._meeting_detect_state == 'idle':
                                self._meeting_detect_state = 'running'
                                self._meeting_detect_user_kept_recording = False
                        state = 'running'
                        log.info("Adopted manual meeting for call-end detection (%s)", kind)
                    # Decide whether to PROMPT to start an auto-meeting.
                    # Only do so from 'idle' state with no other meeting
                    # already running and only after the signal is
                    # stable for START_CONFIRM_POLLS consecutive polls.
                    if (state == 'idle' and not meeting_active and
                            self._meeting_detect_consec_present >= START_CONFIRM_POLLS and
                            kind not in self._meeting_detect_dismissed_kinds):
                        log.info("Meeting detected (%s): %s", kind,
                                 _fmt_user_text(self.config, title))
                        self._show_meeting_start_prompt(kind, title)
                else:
                    self._meeting_detect_consec_present = 0
                    self._meeting_detect_consec_absent += 1
                    # Close a stale Start prompt + clear dismissed kinds
                    # quickly (10s) — the user-pending prompt should go
                    # away when the call ends, and the next call should
                    # be eligible for a fresh prompt.
                    if self._meeting_detect_consec_absent >= START_CONFIRM_POLLS:
                        if self._meeting_detect_dismissed_kinds:
                            self._meeting_detect_dismissed_kinds = set()
                        if state == 'prompting_start':
                            log.info("Call ended before user action — closing Start prompt")
                            self._close_start_prompt_silently()
                    # Stop prompt requires a MUCH longer absence (60s) so
                    # normal silences in a Teams call don't trip it. The
                    # detector's audio-session-Active signal goes Inactive
                    # any time nobody is speaking; only sustained absence
                    # is a real call-ended signal.
                    if (self._meeting_detect_consec_absent >= STOP_CONFIRM_POLLS and
                            state == 'running' and meeting_active and
                            not self._meeting_detect_user_kept_recording):
                        log.info("Call ended (audio absent %.0fs) — offering to stop the auto-meeting",
                                 self._meeting_detect_consec_absent * POLL_INTERVAL)
                        self._show_meeting_stop_prompt()
            except Exception as e:
                log.warning("Meeting detector iteration failed: %s", e)

            if self._meeting_detect_stop_event.wait(POLL_INTERVAL):
                break

    def _show_meeting_start_prompt(self, kind, title):
        """Transition to prompting_start and show the clickable overlay."""
        with self._meeting_detect_lock:
            if self._meeting_detect_state != 'idle':
                return
            self._meeting_detect_state = 'prompting_start'

        # Per-kind body text. Title is included only when it's plausibly
        # informative — for Meet/Teams it contains the meeting name.
        kind_label = {'zoom': 'Zoom', 'teams': 'Microsoft Teams',
                      'meet': 'Google Meet'}.get(kind, kind.title())
        body = f"{kind_label} call is active.\nStart recording?"

        def on_start():
            log.info("User accepted Start prompt for %s", kind)
            with self._meeting_detect_lock:
                self._meeting_detect_state = 'running'
                self._meeting_detect_user_kept_recording = False
                # Reset absent counter so the Stop-prompt 60s window
                # starts FRESH from the meeting start, not from any
                # absent counts that may have accumulated while the
                # prompt was being shown.
                self._meeting_detect_consec_absent = 0
            # _start_meeting is heavy (model resolve, API check, recorder
            # warm-up) — fire on its own thread so we don't block the
            # Tk thread that fired the callback. Auto-detected meetings
            # default to WITH summary — the high-value path when joining a call.
            self._start_meeting(summarize=True)
            # _start_meeting has several silent refuse paths (missing key,
            # press-to-talk active, compose active, start failure). If no
            # meeting actually started, ROLL BACK to idle — otherwise the
            # detector was wedged in 'running' forever and never prompted
            # again for the rest of the app's uptime.
            if not self._is_meeting_active():
                log.info("Start prompt accepted but meeting did not start — "
                         "resetting detector to idle")
                with self._meeting_detect_lock:
                    if self._meeting_detect_state == 'running':
                        self._meeting_detect_state = 'idle'

        def on_dismiss():
            log.info("User dismissed Start prompt for %s", kind)
            with self._meeting_detect_lock:
                if self._meeting_detect_state == 'prompting_start':
                    self._meeting_detect_state = 'idle'
                self._meeting_detect_dismissed_kinds.add(kind)

        try:
            self.overlay.show_prompt(
                header=f"🎙  {kind_label} meeting detected",
                body=body,
                button_label='🎙  Start recording',
                on_action=on_start,
                on_dismiss=on_dismiss,
                duration_ms=6500,  # auto-dismiss in ~6.5s — no need to click ✕
            )
        except Exception as e:
            log.warning("Failed to show Start prompt: %s", e)
            with self._meeting_detect_lock:
                self._meeting_detect_state = 'idle'

    def _close_start_prompt_silently(self):
        """Forcibly transition prompting_start → idle when the call ended
        before the user clicked. The overlay's own auto-dismiss timer
        will close the Toplevel; we just reset our state."""
        with self._meeting_detect_lock:
            if self._meeting_detect_state == 'prompting_start':
                self._meeting_detect_state = 'idle'

    def _show_meeting_stop_prompt(self, reason="call-end", silent_min=0):
        """A meeting is still recording but looks over — offer to stop.

        reason='call-end'  → the auto-detect loop saw 60s of sustained call
                             absence (requires detector state 'running').
        reason='silence'   → the watchdog saw meeting_silence_prompt_min of
                             continuous silence in the RECORDING itself.
                             Allowed from 'idle' too — manual meetings that
                             were never adopted (no call detected) sit in
                             'idle' and previously could NEVER get this offer.

        Button semantics: '⏹ Stop' stops; '✕' = deliberate keep-recording
        (suppresses further offers this meeting); TIMEOUT = user away —
        return to the previous state so the offer re-arms."""
        # Anti-spam: after a few UNANSWERED offers the user is clearly away —
        # stop nagging and let the silence/hard-cap AUTO-stop take over. Without
        # this, on_timeout re-armed the call-end offer every ~2 min (a card AND
        # a tray balloon each) for the rest of the meeting → dozens of pop-ups.
        if getattr(self, "_stop_offer_count", 0) >= 3:
            return
        with self._meeting_detect_lock:
            st = self._meeting_detect_state
            if reason == "call-end":
                if st != 'running':
                    return
                prev_state = 'running'
            else:
                if st not in ('idle', 'running'):
                    return
                prev_state = st
            self._meeting_detect_state = 'prompting_stop'
        first_offer = getattr(self, "_stop_offer_count", 0) == 0

        def on_stop():
            log.info("User accepted Stop prompt (%s) — finalising meeting", reason)
            self._stop_offer_count = 0
            with self._meeting_detect_lock:
                self._meeting_detect_state = 'idle'
                self._meeting_detect_user_kept_recording = False
            self._stop_meeting()

        def on_continue():
            log.info("User kept recording past %s prompt", reason)
            # Explicit ✕ → stop offering for the rest of the meeting.
            self._stop_offer_count = 999
            with self._meeting_detect_lock:
                if self._meeting_detect_state == 'prompting_stop':
                    self._meeting_detect_state = prev_state
                self._meeting_detect_user_kept_recording = True

        def on_timeout():
            # No user action — the user-walked-away case this prompt exists
            # for. Do NOT treat it as a deliberate 'keep recording' (that
            # permanently disqualified any future stop prompt — verified in
            # the 06-04/06-09 logs: 'kept recording' fired exactly 30s after
            # each offer, i.e. the timeout, and the user never saw another
            # offer); return to the previous state so the nets re-arm — but
            # count it, so 3 unanswered offers stop the nagging (above).
            self._stop_offer_count = getattr(self, "_stop_offer_count", 0) + 1
            log.info("Stop prompt (%s) timed out (#%d) — will re-offer up to 3x",
                     reason, self._stop_offer_count)
            with self._meeting_detect_lock:
                if self._meeting_detect_state == 'prompting_stop':
                    self._meeting_detect_state = prev_state
                self._meeting_detect_consec_absent = 0

        if reason == "silence":
            header = '⏹  Meeting seems over'
            mins = silent_min or int(self.config.get(
                "meeting_silence_prompt_min", 5) or 5)
            body = (f"No voice for ~{mins} min but the meeting is still "
                    "recording.\nStop the recording?")
        else:
            header = '⏹  Call ended'
            body = 'The detected call ended.\nStop the recording?'

        try:
            self.overlay.show_prompt(
                header=header,
                body=body,
                button_label='⏹  Stop recording',
                on_action=on_stop,
                on_dismiss=on_continue,
                # 60s window (was 30s): this fires exactly when the user is
                # wrapping up / stepping away — give it room to be noticed.
                duration_ms=60000,
                on_timeout=on_timeout,
            )
            # Tray balloon ONLY on the first offer of an away-episode — firing
            # it on every re-offer was the notification-center spam.
            if first_offer:
                try:
                    if self.tray_icon:
                        self.tray_icon.notify(
                            "Meeting still recording — click the on-screen card "
                            "to stop", "Lia")
                except Exception:
                    pass
        except Exception as e:
            log.warning("Failed to show Stop prompt: %s", e)
            with self._meeting_detect_lock:
                if self._meeting_detect_state == 'prompting_stop':
                    self._meeting_detect_state = prev_state

    def _save_vocabulary(self, new_vocab):
        """Persist edited custom_vocabulary + live-update the transcribers so the
        next recording uses it without a restart. Runs on the overlay Tk thread;
        raises on write failure so the editor can surface an error."""
        new_vocab = (new_vocab or "").strip()
        self.config["custom_vocabulary"] = new_vocab
        save_config(self.config)
        # Sync the self-learning store: new manual terms become starred;
        # deleted ones are demoted so the miner never resurfaces them.
        if getattr(self, "_vocab_store", None) is not None:
            try:
                self._vocab_store.set_manual_terms(new_vocab)
            except Exception as e:
                log.warning("Vocabulary store sync failed: %s", e)
        self._push_vocabulary_live()
        log.info("Custom vocabulary saved (%d chars manual)", len(new_vocab))

    # ================= Self-learning vocabulary (vocab_learn.py) =================
    # The portable module owns the store/miner/composer (reusable by
    # a private upstream project); these methods are Lia's thin wiring: composition
    # into every Whisper prompt, the tray review flow, corpus mining, and the
    # usage-ranking observation hook.

    def _composed_vocabulary(self):
        """Effective vocabulary string for Whisper prompts / LLM cleanup: the
        ranked, budgeted composition from the self-learning store — falling
        back to the raw manual list when the store is unavailable. This is the
        SINGLE choke point every transcriber push-site reads."""
        store = getattr(self, "_vocab_store", None)
        if store is not None:
            try:
                return store.compose_prompt(
                    int(self.config.get("vocab_prompt_budget_chars", 600)))
            except Exception as e:
                log.warning("Vocabulary compose failed — using manual list: %s", e)
        return self.config.get("custom_vocabulary") or ""

    def _push_vocabulary_live(self):
        """Push the current composed vocabulary into every LIVE transcriber
        (dictation backends + cached meeting/file transcribers) so the next
        recording uses it without a restart."""
        vocab = self._composed_vocabulary()
        targets = [getattr(self, n, None) for n in
                   ("_local_transcriber", "_groq_transcriber",
                    "_openai_transcriber", "_remote_transcriber")]
        targets += [triple[0] for triple in
                    getattr(self, "_meeting_xcribers", {}).values()
                    if triple and triple[0] is not None]
        for t in targets:
            if t is not None:
                try:
                    t.custom_vocabulary = vocab
                except Exception:
                    pass

    # Conservative first-seed of the corrections table: recurring garbles found
    # while curating the real corpus (2026-08-14). Whole-word fixes only; risky
    # ambiguous ones (cash/WAP/IAS) deliberately left out.
    _VOCAB_CORRECTIONS_SEED = [
        {"wrong": "Bedrook", "right": "Bedrock"},
        {"wrong": "Bed-Roc", "right": "Bedrock"},
        {"wrong": "Bedrok", "right": "Bedrock"},
        {"wrong": "Lending Zone", "right": "Landing Zone"},
        {"wrong": "Enter ID", "right": "Entra ID"},
        {"wrong": "EnterID", "right": "Entra ID"},
        {"wrong": "NTRID", "right": "Entra ID"},
        {"wrong": "GARD DUTY", "right": "GuardDuty"},
        {"wrong": "E.K.S", "right": "EKS"},
        {"wrong": "CloudTrain", "right": "CloudTrail"},
    ]

    def _vocab_apply_corrections(self, text, extra_pairs=None, label=""):
        """Apply the STORED corrections table (+ optional fresh pairs) to
        `text`. Deterministic whole-word replace; every application is logged;
        config kill-switch vocab_corrections. Returns the (possibly) fixed
        text — never raises."""
        store = getattr(self, "_vocab_store", None)
        if (store is None or vocab_learn is None or not text
                or not self.config.get("vocab_corrections", True)):
            return text
        try:
            pairs = store.corrections() + list(extra_pairs or [])
            fixed, counts = vocab_learn.apply_corrections(text, pairs)
            if counts:
                store.record_applied(counts)
                log.info("Vocab corrections applied (%s): %s", label or "text",
                         _fmt_user_text(self.config,
                                        ", ".join("%s×%d" % kv for kv in counts.items())))
            return fixed
        except Exception as e:
            log.warning("Vocab corrections failed (%s): %s", label, e)
            return text

    def _vocab_take_corrections(self, source="summary"):
        """Collect the pairs the summary model just proposed (cleaner
        .last_corrections), persist the guard-approved ones to the store for
        FUTURE transcripts, and return them for immediate application."""
        store = getattr(self, "_vocab_store", None)
        cleaner = getattr(self, "_summary_cleaner", None)
        pairs = list(getattr(cleaner, "last_corrections", []) or [])
        if not pairs or store is None:
            return pairs
        try:
            added = store.add_corrections(pairs, source=source)
            if added:
                log.info("Vocab corrections learned from %s: %d new (e.g. %s)",
                         source, added,
                         "; ".join("%s→%s" % (p["wrong"], p["right"])
                                   for p in pairs[:3]))
        except Exception as e:
            log.warning("Vocab corrections persist failed: %s", e)
        return pairs

    def _vocab_pending_count(self):
        store = getattr(self, "_vocab_store", None)
        try:
            return store.pending_count() if store else 0
        except Exception:
            return 0

    def _vocab_observe(self, text):
        """Usage-ranking hook: called with every produced transcript (dictation
        + meeting chunks). Buffered inside the store — cheap, never raises."""
        store = getattr(self, "_vocab_store", None)
        if store is None or not text:
            return
        try:
            store.observe_text(text)
        except Exception:
            pass

    def _vocab_corpus_texts(self):
        """All mineable text: meeting transcripts (.txt/.md) + dictation
        history entries. Generator-free simple list — the corpus is small
        (~3MB) and the miner is a one-pass scan."""
        texts = []
        try:
            import glob as _glob
            for pat in ("*.txt", "*.md"):
                for p in _glob.glob(os.path.join(MEETINGS_DIR, pat)):
                    try:
                        with open(p, encoding="utf-8") as f:
                            texts.append(f.read())
                    except Exception:
                        pass
        except Exception as e:
            log.warning("Vocab mine: meetings scan failed: %s", e)
        try:
            with open(HISTORY_FILE, encoding="utf-8") as f:
                data = json.load(f)
            entries = data if isinstance(data, list) else data.get("entries", [])
            texts.extend((e.get("text") or "") for e in entries
                         if isinstance(e, dict))
        except Exception:
            pass
        return texts

    # Words that appear in Lia's OWN transcript-file format (headers,
    # timestamps, failure markers) — they'd dominate any corpus mine as
    # false "vocabulary" ("Speaker" showed up 5958x on the first real run).
    # Suppressed at mine time; a real spoken use later can still be added
    # manually. All lowercase (miner keys are normalized).
    _VOCAB_FORMAT_NOISE = frozenset((
        "speaker", "meeting", "meetings", "summary", "transcript",
        "transcription", "transcription failed", "duration", "generated",
        "recap", "engine", "chunks", "chunk", "live", "html", "source",
        "lia", "whispertype", "assemblyai", "pyannote",
    ))

    def _vocab_mine_texts_async(self, texts, source, notify=False):
        """Mine `texts` for new candidate terms on a worker thread; new
        suggestions accumulate silently as a (N) badge on the Review item."""
        store = getattr(self, "_vocab_store", None)
        if store is None or vocab_learn is None:
            if notify:
                self.overlay.show_error("Vocabulary store unavailable")
            return
        # 2026-08: the miner's Latin-token heuristic is tuned for Hebrew-heavy
        # corpora (any embedded Latin token = likely domain vocabulary). On
        # MOSTLY-ENGLISH texts every content word would become a candidate,
        # held back only by the stopword list - skip those texts. Manual
        # terms + corrections keep working for English; an EN-aware miner
        # is a post-release experiment.
        texts = [t for t in texts if lang_pack.detect_text_lang(t) == "he"]
        if not texts:
            if notify:
                self.overlay.show_error("Vocabulary mining is Hebrew-only for now")
            else:
                log.info("Vocab miner (%s): all texts English - skipped", source)
            return

        def worker():
            try:
                cands = vocab_learn.mine_texts(
                    texts,
                    known=store.known_keys() | self._VOCAB_FORMAT_NOISE,
                    min_freq=int(self.config.get("vocab_min_freq", 3)))
                added = store.add_candidates(cands, source=source)
                log.info("Vocab miner (%s): %d texts → %d candidates, %d new",
                         source, len(texts), len(cands), added)
                if self.tray_icon:
                    try:
                        self.tray_icon.update_menu()
                    except Exception:
                        pass
                if notify:
                    if added:
                        try:
                            self.tray_icon.notify(
                                "%d new term suggestions — review them under "
                                "Options → Meetings → Custom Vocabulary."
                                % added, "Lia")
                        except Exception:
                            pass
                    else:
                        self.overlay.show("  ✓  No new terms found  ",
                                          bg_color="#4c6085", duration=2000)
            except Exception as e:
                log.exception("Vocab miner failed: %s", e)
                if notify:
                    self.overlay.show_error("Vocabulary scan failed")
        threading.Thread(target=worker, daemon=True).start()

    def _vocab_rebuild(self):
        """Tray action: full corpus scan (meetings + history) for new terms."""
        self.overlay.show("  🔎  Scanning meetings for terms…  ",
                          bg_color="#1e64c8", duration=3000)
        self._vocab_mine_texts_async(self._vocab_corpus_texts(),
                                     source="corpus", notify=True)

